insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('character-strengths-checklist', 'Character Strengths Checklist', 'worksheet'::resource_kind, 'A checklist of strength words a client circles, ranks and backs up with real examples.', 'Use it to build a shared vocabulary for the strengths a client already has.', array['Adults', 'Teens']::text[], '20 minutes', 'The client scans a list of strength words, circling any that fit, then narrows to a top five and writes one specific recent moment for each rather than a general trait. Some clients rush to modest, vague answers or skip strengths they feel they haven''t earned; slow them down and press for a concrete example. Useful as an opener before goal-setting or values work, since it hands the clinician language the client already owns.', '[{"id": "f0", "type": "textarea", "label": "Circle every strength word below that sounds like you."}, {"id": "f1", "type": "textarea", "label": "From those, pick your top five and put them in order."}, {"id": "f2", "type": "textarea", "label": "Write one specific recent moment you used your top strength."}, {"id": "f3", "type": "textarea", "label": "Which strength do you use so often you forget it counts?"}, {"id": "f4", "type": "textarea", "label": "Which strength would you like to use more this month?"}, {"id": "f5", "type": "textarea", "label": "Who in your life would agree with this list, and who might be surprised?"}]'::jsonb, array['strengths', 'psychoeducation', 'self-monitoring']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('boundary-practice-hierarchy', 'Boundary Practice Hierarchy', 'worksheet'::resource_kind, 'A ranked list of boundary-setting situations from easiest to hardest to practice in order.', 'Use it to sequence boundary practice so a client builds confidence gradually.', array['Adults', 'Teens']::text[], 'One week', 'The client lists situations where they''d like to hold a boundary, then ranks them from easiest to hardest and picks a script for the easiest one to try first. Clients often want to start with the hardest relationship on the list; steer them toward a low-stakes situation so an early success builds momentum. Revisit the ranking each week, moving down the list only after a step feels manageable, and use the sheet to plan what to say and how to handle pushback.', '[{"id": "f0", "type": "textarea", "label": "List five situations where you wish you set a clearer boundary."}, {"id": "f1", "type": "textarea", "label": "Rank them from easiest (1) to hardest (5) to practice."}, {"id": "f2", "type": "textarea", "label": "Write the exact words you''ll use for your easiest one."}, {"id": "f3", "type": "textarea", "label": "What do you expect the other person to say back?"}, {"id": "f4", "type": "textarea", "label": "How will you respond if they push back?"}, {"id": "f5", "type": "textarea", "label": "After you try it, what actually happened?"}]'::jsonb, array['boundaries', 'assertiveness', 'hierarchy']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('habit-stacking-planner', 'Habit Stacking Planner', 'worksheet'::resource_kind, 'A worksheet that attaches a new habit to a routine the client already does daily.', 'Use it to help a client anchor a new habit to an existing one instead of relying on willpower.', array['Adults', 'Teens']::text[], 'Five minutes daily for several weeks', 'The client names a small habit they already do without thinking, like making coffee or brushing their teeth, and attaches the new habit right after it using an if-then sentence. The most common trip-up is choosing a new habit that''s too big or an anchor habit that doesn''t happen at a consistent time; help them shrink both. Check in on the stack each week and adjust the anchor or the size of the habit rather than abandoning the idea.', '[{"id": "f0", "type": "textarea", "label": "What''s a small habit you already do every day without thinking?"}, {"id": "f1", "type": "textarea", "label": "What new habit do you want to build?"}, {"id": "f2", "type": "textarea", "label": "Finish this: After I [anchor habit], I will [new habit]."}, {"id": "f3", "type": "textarea", "label": "How will you make the new habit take less than two minutes at first?"}, {"id": "f4", "type": "textarea", "label": "What might get in the way this week?"}, {"id": "f5", "type": "textarea", "label": "How did the stack go by the end of the week?"}]'::jsonb, array['habits', 'self-monitoring', 'motivation']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('listening-skills-self-check', 'Listening Skills Self-Check', 'worksheet'::resource_kind, 'A self-rating sheet where a client scores their own listening habits in real conversations.', 'Use it to help a client notice which listening habits help and which ones interrupt.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'The client rates how often they interrupt, plan their reply while the other person is talking, or reflect back what they heard, then picks one habit to work on this week. Clients often rate themselves generously; asking for a specific recent conversation as evidence sharpens the answers. Pair it with a short role-play in session so the clinician can point out what the client''s own ratings missed.', '[{"id": "f0", "type": "textarea", "label": "How often do you interrupt before the other person finishes?"}, {"id": "f1", "type": "textarea", "label": "How often are you planning your reply instead of listening?"}, {"id": "f2", "type": "textarea", "label": "How often do you check what you heard by repeating it back?"}, {"id": "f3", "type": "textarea", "label": "Describe a recent conversation where you listened well."}, {"id": "f4", "type": "textarea", "label": "Describe one where you wish you''d listened differently."}, {"id": "f5", "type": "textarea", "label": "Which listening habit will you practice this week?"}]'::jsonb, array['communication', 'listening', 'self-monitoring']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('stress-curve-psychoeducation-sheet', 'Stress Curve Psychoeducation Sheet', 'worksheet'::resource_kind, 'A diagram showing how performance rises then falls as stress and arousal increase.', 'Use it to help a client see that some stress helps and too much or too little hurts.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk the client through a simple curve showing performance climbing with mild stress, peaking, then dropping as stress builds further, and ask them to mark where they usually sit day to day. Clients sometimes hear this as permission to chase more stress rather than as a way to notice when they''ve tipped past their peak; keep the focus on their own signs of tipping over, not a general rule. Use their markings to plan one small change that nudges them back toward the peak.', '[{"id": "f0", "type": "textarea", "label": "Where on the curve do you usually sit most days?"}, {"id": "f1", "type": "textarea", "label": "What does it feel like in your body when you''re on the rising side?"}, {"id": "f2", "type": "textarea", "label": "What does it feel like when you''ve tipped past the peak?"}, {"id": "f3", "type": "textarea", "label": "What''s one sign that tells you you''ve gone too far?"}, {"id": "f4", "type": "textarea", "label": "What''s one thing that brings you back down the curve?"}]'::jsonb, array['psychoeducation', 'stress', 'self-monitoring']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('anxietys-job-description-worksheet', 'Anxiety''s Job Description Worksheet', 'worksheet'::resource_kind, 'Explores what a client believes their anxiety is trying to accomplish for them.', 'Use it to surface the protective story behind anxiety and weigh its actual payoff.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to write anxiety''s ''job description'' as if it were an employee: what it thinks its duties are, what it believes would happen if it stopped working so hard, and what it actually costs the client in energy or missed moments. Clients often list only the downsides of anxiety and skip what they believe it protects them from; push gently for both sides. Use the finished sheet to open a conversation about which duties still feel needed and which could be handed off or scaled back.', '[{"id": "f0", "type": "textarea", "label": "If anxiety had a job title, what would it be?"}, {"id": "f1", "type": "textarea", "label": "What does anxiety believe would happen if it stopped doing this job?"}, {"id": "f2", "type": "textarea", "label": "What does this job cost you day to day?"}, {"id": "f3", "type": "textarea", "label": "Which part of this job feels like it could be scaled back?"}, {"id": "f4", "type": "textarea", "label": "What would you do with the energy anxiety is currently spending?"}]'::jsonb, array['anxiety', 'worry', 'self-monitoring']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('minimum-viable-day-planner', 'Minimum Viable Day Planner', 'worksheet'::resource_kind, 'Lays out the smallest version of a day a client can still call a win.', 'Use it to lower the bar on low-energy days without abandoning structure entirely.', array['Adults', 'Teens']::text[], '15 minutes', 'Work with the client to list the smallest possible version of each daily task, such as a two-minute shower instead of a full routine, so there is always a version they can complete on a low day. Clients often set the minimum version too high out of habit; keep pushing it smaller until they visibly relax about it. Use the sheet on genuinely hard mornings rather than every day, and review afterward whether the minimum version still counted as something worth noticing.', '[{"id": "f0", "type": "textarea", "label": "List three tasks you usually do in a day."}, {"id": "f1", "type": "textarea", "label": "What is the smallest possible version of each one?"}, {"id": "f2", "type": "textarea", "label": "Which minimum version did you complete today?"}, {"id": "f3", "type": "textarea", "label": "How did it feel to do the smaller version instead of skipping it?"}, {"id": "f4", "type": "textarea", "label": "What would make tomorrow''s minimum version even easier to start?"}]'::jsonb, array['depression', 'behavioral activation', 'self-monitoring']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('life-beyond-substance-use-sheet', 'Life Beyond Substance Use Sheet', 'worksheet'::resource_kind, 'Maps the roles, activities, and people that exist apart from substance use.', 'Use it to widen a client''s sense of identity beyond substance use and urges.', array['Adults']::text[], '20 minutes', 'Have the client list roles, activities, and relationships that matter to them and are not organized around substance use, then rate how much attention each currently gets. Clients in early recovery often find this list thinner than expected, which is useful information rather than a failure. Use the sheet to pick one under-attended area to invest a small amount of time in this week, and revisit it periodically as the list of what matters outside urges naturally grows.', '[{"id": "f0", "type": "textarea", "label": "List three roles or relationships that matter to you."}, {"id": "f1", "type": "textarea", "label": "List two activities you enjoy that have nothing to do with substance use."}, {"id": "f2", "type": "textarea", "label": "How much attention has each one gotten lately, 0 to 10?"}, {"id": "f3", "type": "textarea", "label": "Which one would you like to invest a little more time in this week?"}, {"id": "f4", "type": "textarea", "label": "What is one small step toward that this week?"}]'::jsonb, array['addiction', 'values', 'substance use']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('anger-trigger-stack-worksheet', 'Anger Trigger Stack Worksheet', 'worksheet'::resource_kind, 'Tracks the small stressors that pile up before a single anger blow-up.', 'Use it to make the buildup before an outburst visible, not just the final trigger.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client walk back through a recent anger episode and list every small stressor that stacked up beforehand, not just the final straw, noting roughly how full the stack felt at each point on a scale. Clients often can only name the last trigger; use guided questions about the hours before to surface the earlier layers. Once the stack is visible, identify one layer that could be unloaded earlier next time, such as a break or a boundary, well before the stack gets close to full.', '[{"id": "f0", "type": "textarea", "label": "What was the final trigger right before the anger episode?"}, {"id": "f1", "type": "textarea", "label": "List the smaller stressors from earlier that day."}, {"id": "f2", "type": "textarea", "label": "How full did the stack feel at each point, 0 to 10?"}, {"id": "f3", "type": "textarea", "label": "Which layer could you unload earlier next time?"}, {"id": "f4", "type": "textarea", "label": "What would unloading it look like in the moment?"}]'::jsonb, array['anger management', 'triggers', 'self-monitoring']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('compulsion-function-log', 'Compulsion Function Log', 'worksheet'::resource_kind, 'Tracks what each ritual actually relieves, not just how long it takes.', 'Use it to map what a ritual quiets so exposure work targets the right worry.', array['Adults', 'Teens']::text[], 'One week', 'Have the client log each ritual for a week, noting the trigger, the specific worry it seems to quiet, and how long relief lasts before the urge returns; most people are surprised to see one or two worries driving several different rituals, which helps target exposure and response prevention work instead of chasing every compulsion at once.', '[{"id": "f0", "type": "textarea", "label": "What happened right before I felt the urge?"}, {"id": "f1", "type": "textarea", "label": "What ritual did I do?"}, {"id": "f2", "type": "textarea", "label": "What worry was I trying to quiet?"}, {"id": "f3", "type": "textarea", "label": "How long did the relief last?"}, {"id": "f4", "type": "textarea", "label": "What would have happened if I hadn''t done it?"}]'::jsonb, array['OCD', 'exposure', 'function analysis']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('positive-attention-ratio-tracker', 'Positive Attention Ratio Tracker', 'worksheet'::resource_kind, 'Counts positive comments against corrections across an ordinary day.', 'Use it to rebalance a day that has drifted toward mostly correcting a child.', array['Adults']::text[], 'One day', 'Have the parent make two simple tallies through one ordinary day, one for comments that noticed something good and one for corrections, warnings, or commands; use the ratio as a plain baseline for later work rather than a verdict on the parent, since most parents are startled by how lopsided the count turns out to be.', '[{"id": "f0", "type": "textarea", "label": "Tally: things I said that noticed something good."}, {"id": "f1", "type": "textarea", "label": "Tally: corrections, warnings, or commands I gave."}, {"id": "f2", "type": "textarea", "label": "What surprised me about the count?"}, {"id": "f3", "type": "textarea", "label": "What is one moment today I could have narrated positively instead?"}]'::jsonb, array['parenting', 'behavioral', 'self-monitoring']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('new-parent-support-needs-inventory', 'New Parent Support Needs Inventory', 'worksheet'::resource_kind, 'Sorts what kind of help a new parent actually needs by category.', 'Use it to turn a vague need for help into requests others can act on.', array['Adults']::text[], '20 minutes', 'Have the client list needs across practical tasks, emotional support, information, and time alone, then name a specific person for each rather than leaving it as a general wish for more help; this pairs well with a later partner conversation, and clients often stall not at listing needs but at naming who to actually ask.', '[{"id": "f0", "type": "textarea", "label": "Practical tasks I need help with right now."}, {"id": "f1", "type": "textarea", "label": "Emotional support I need right now."}, {"id": "f2", "type": "textarea", "label": "Information or reassurance I need right now."}, {"id": "f3", "type": "textarea", "label": "Who could I actually ask for each of these?"}, {"id": "f4", "type": "textarea", "label": "What is stopping me from asking?"}]'::jsonb, array['perinatal and postpartum', 'support', 'planning']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('pre-event-body-signal-checklist', 'Pre-Event Body Signal Checklist', 'worksheet'::resource_kind, 'Catalogs the physical warning signs that show up before a social event.', 'Use it to help someone recognize their own pattern of anticipatory signals.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client check off which physical signals typically appear in the hours before a social event, such as a tight stomach, rehearsing lines, or repeated mirror checks, and rate each one across a few events; the same one or two signals usually show up earliest and most reliably, which can become a cue to use a coping skill rather than a reason to cancel.', '[{"id": "f0", "type": "textarea", "label": "Which body signals show up before a social event?"}, {"id": "f1", "type": "textarea", "label": "Rate each one from mild to strong."}, {"id": "f2", "type": "textarea", "label": "Which signal shows up earliest, most reliably?"}, {"id": "f3", "type": "textarea", "label": "What could that early signal remind me to do?"}]'::jsonb, array['social anxiety', 'body awareness', 'self-monitoring']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('secondary-losses-inventory', 'Secondary Losses Inventory', 'worksheet'::resource_kind, 'Maps the smaller losses that ripple out from a single death or ending.', 'Use it to help a client name what else changed besides the loss itself.', array['Adults']::text[], '20 minutes', 'Hand this to a client who feels stuck on one big loss without noticing everything that shifted around it — a routine, a role, a sense of safety, a social circle. Walk through each life area together and list what quietly went missing too. Clients often name only the person or thing lost at first; give them time and prompts to notice the secondary losses, since naming them can explain why grief feels bigger than the loss alone. Watch for a client who uses this to catalog blame rather than loss.', '[{"id": "f0", "type": "textarea", "label": "One loss I can name right away is…"}, {"id": "f1", "type": "textarea", "label": "A daily routine that changed because of this loss is…"}, {"id": "f2", "type": "textarea", "label": "A role I used to have that feels different now is…"}, {"id": "f3", "type": "textarea", "label": "A sense of safety or certainty I lost along with this is…"}, {"id": "f4", "type": "textarea", "label": "A relationship or connection that shifted because of this loss is…"}, {"id": "f5", "type": "textarea", "label": "The smallest change I''ve noticed that still catches me off guard is…"}]'::jsonb, array['grief and loss', 'secondary loss', 'bereavement']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('autonomy-and-togetherness-balance-sheet', 'Autonomy and Togetherness Balance Sheet', 'worksheet'::resource_kind, 'Maps how much separateness and closeness each partner wants right now.', 'Use it to help a client see where their needs for space and closeness diverge from a partner''s.', array['Adults']::text[], '20 minutes', 'Have the client plot, on a simple scale, how much time alone versus together they want in a typical week, then guess where they think their partner would plot it, and compare notes afterward if both partners complete it. Differences here are common and not a verdict on the relationship; the point is naming the gap out loud instead of each partner privately deciding the other wants too much or too little. Watch for a client who fills this out defensively, trying to prove they are the reasonable one rather than describe their actual preference.', '[{"id": "f0", "type": "textarea", "label": "On a typical week, the amount of time alone I want is…"}, {"id": "f1", "type": "textarea", "label": "The amount of time together I want is…"}, {"id": "f2", "type": "textarea", "label": "Where I think my partner would place their own numbers…"}, {"id": "f3", "type": "textarea", "label": "A time recently when this gap showed up between us…"}, {"id": "f4", "type": "textarea", "label": "One small adjustment I could make this week…"}]'::jsonb, array['relationship issues', 'autonomy', 'communication']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('coping-swap-ladder', 'Coping Swap Ladder', 'worksheet'::resource_kind, 'Ranks unhelpful coping habits next to an easier and a harder helpful swap.', 'Use it to help a client find a realistic first step away from an unhelpful habit.', array['Adults']::text[], '20 minutes', 'List the client''s go-to unhelpful coping habits down one side, then for each one brainstorm two swaps: an easy one they could try today and a harder one for later, ranked by difficulty rather than treated as an all-or-nothing switch. Clients often reach straight for the hardest swap and then feel like a failure when it doesn''t stick; steer them toward the easy swap first and let the ladder show progress over time. Revisit the ladder every few sessions to move entries up as easier swaps become automatic.', '[{"id": "f0", "type": "textarea", "label": "An unhelpful habit I turn to under stress…"}, {"id": "f1", "type": "textarea", "label": "An easier helpful swap I could try today…"}, {"id": "f2", "type": "textarea", "label": "A harder helpful swap for later…"}, {"id": "f3", "type": "textarea", "label": "What usually gets in the way of trying the swap…"}, {"id": "f4", "type": "textarea", "label": "One thing that would make the easy swap more likely…"}]'::jsonb, array['coping skills', 'habits', 'self-monitoring']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('anticipation-countdown-tracker', 'Anticipation Countdown Tracker', 'worksheet'::resource_kind, 'Logs dread levels in the days leading up to a planned exposure or feared event.', 'Use it to show a client how anticipatory dread moves compared to the event itself.', array['Adults', 'Teens']::text[], 'One week', 'Before a planned exposure step or an unavoidable feared event, have the client rate their dread once a day counting down, then rate it again right after the event happens. Most clients are surprised to see dread peak well before the event and drop faster afterward than expected; use the chart to make that pattern visible rather than just telling them about it. Watch for a client who avoids logging on the hardest days, which itself is useful information about avoidance patterns.', '[{"id": "f0", "type": "textarea", "label": "The event or exposure step I''m counting down to…"}, {"id": "f1", "type": "textarea", "label": "Three days before: dread level, 0 to 10…"}, {"id": "f2", "type": "textarea", "label": "One day before: dread level, 0 to 10…"}, {"id": "f3", "type": "textarea", "label": "The morning of: dread level, 0 to 10…"}, {"id": "f4", "type": "textarea", "label": "Right after: dread level, 0 to 10…"}, {"id": "f5", "type": "textarea", "label": "What I notice comparing the numbers…"}]'::jsonb, array['phobias', 'self-monitoring', 'exposure']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('smart-goal-builder', 'SMART Goal Builder', 'cbt'::resource_kind, 'A step-by-step sheet that turns a vague goal into a specific, measurable plan.', 'Use it to help a client turn a wish into a goal they can actually track.', array['Adults', 'Teens']::text[], '20 minutes', 'The client takes one goal and rewrites it against five prompts, specific, measurable, achievable, relevant and time-bound, until it reads as a concrete plan rather than a wish. Clients often keep the goal too broad, such as be less stressed, or set a deadline with no way to check progress; push for a number or an observable sign. Once the goal is sharpened, use it as the anchor for weekly check-ins on progress.', '[{"id": "f0", "type": "textarea", "label": "What''s the vague version of your goal right now?"}, {"id": "f1", "type": "textarea", "label": "What exactly will be different when you reach it?"}, {"id": "f2", "type": "textarea", "label": "How will you measure or notice progress along the way?"}, {"id": "f3", "type": "textarea", "label": "Is this goal realistic for you in this stretch of time?"}, {"id": "f4", "type": "textarea", "label": "Why does this goal matter to you right now?"}, {"id": "f5", "type": "textarea", "label": "What''s your target date?"}]'::jsonb, array['goal setting', 'core CBT', 'motivation']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('barriers-and-bridges-planner', 'Barriers and Bridges Planner', 'cbt'::resource_kind, 'A worksheet that pairs each barrier to a goal with a specific bridge past it.', 'Use it to turn a stuck goal into a list of concrete next moves.', array['Adults', 'Teens']::text[], '20 minutes', 'The client lists what''s actually getting in the way of a goal, then writes one specific bridge, a person, a resource, or a small action, next to each barrier. Clients tend to name barriers that are really feelings, like I''m too tired, rather than obstacles they can act on; help them separate the feeling from the concrete blocker underneath it. Revisit the bridges weekly and swap out any that turned out not to work.', '[{"id": "f0", "type": "textarea", "label": "What goal do you want to make progress on?"}, {"id": "f1", "type": "textarea", "label": "List every barrier standing in the way, big or small."}, {"id": "f2", "type": "textarea", "label": "Next to each barrier, write one bridge that could get you past it."}, {"id": "f3", "type": "textarea", "label": "Which bridge can you try first, this week?"}, {"id": "f4", "type": "textarea", "label": "Who could help you build one of these bridges?"}]'::jsonb, array['problem solving', 'goal setting', 'core CBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('habit-trigger-chain-log', 'Habit Trigger Chain Log', 'cbt'::resource_kind, 'A log that maps what comes right before and right after a habit the client wants to change.', 'Use it to find the trigger and payoff that keep an unwanted habit going.', array['Adults', 'Teens']::text[], 'One week', 'Each time the habit happens, the client logs what happened just before it, the habit itself, and what happened right after, looking for a repeating trigger and a repeating payoff. Clients often log the habit but skip the moments right before it, since those feel too ordinary to write down; remind them the boring lead-up is usually the trigger. Once a pattern shows up, use the log to test changing the trigger rather than fighting the habit head-on.', '[{"id": "f0", "type": "textarea", "label": "What happened right before the habit, in the ten minutes prior?"}, {"id": "f1", "type": "textarea", "label": "Describe the habit itself: what did you do?"}, {"id": "f2", "type": "textarea", "label": "What happened right after, and how did it feel?"}, {"id": "f3", "type": "textarea", "label": "What time of day and place does this keep happening?"}, {"id": "f4", "type": "textarea", "label": "Looking at a week of entries, what''s the repeating trigger?"}]'::jsonb, array['habits', 'self-monitoring', 'core CBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('decision-matrix-scorecard', 'Decision Matrix Scorecard', 'cbt'::resource_kind, 'A scoring grid that weighs each option in a decision against the client''s own criteria.', 'Use it to help a client compare options on paper instead of going in circles.', array['Adults', 'Teens']::text[], '20 minutes', 'The client lists the options they''re weighing down one side and the criteria that matter to them across the top, then scores each option against each criterion before totaling the columns. Clients sometimes pick criteria that all point the same direction, which just confirms what they already lean toward; ask what a criterion from the other side of the decision would be. The total score is a starting point for discussion, not the final answer.', '[{"id": "f0", "type": "textarea", "label": "What decision are you trying to make?"}, {"id": "f1", "type": "textarea", "label": "List every option you''re seriously considering."}, {"id": "f2", "type": "textarea", "label": "What matters to you in this decision? List three to five criteria."}, {"id": "f3", "type": "textarea", "label": "Score each option from 1 to 5 on each criterion."}, {"id": "f4", "type": "textarea", "label": "Which option came out highest, and does that surprise you?"}]'::jsonb, array['decisions', 'core CBT', 'values']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('emotion-granularity-ladder', 'Emotion Granularity Ladder', 'cbt'::resource_kind, 'A ladder that moves a client from a vague feeling word to a more specific one.', 'Use it to build the emotional vocabulary a client needs for accurate thought records.', array['Adults', 'Teens']::text[], '15 minutes', 'Starting from a vague word like bad or fine, the client climbs a ladder of more specific feeling words until they land on one that actually fits the moment, then names what in the body or situation points to that word. Clients often stop at the second rung because it''s already more specific than they''re used to; encourage one more step before settling. A richer vocabulary here makes later thought records and check-ins far more precise.', '[{"id": "f0", "type": "textarea", "label": "Start with the vague word you''d normally use: how are you feeling?"}, {"id": "f1", "type": "textarea", "label": "Climb one step: what''s a more specific word for that?"}, {"id": "f2", "type": "textarea", "label": "Climb again: is there an even more precise word?"}, {"id": "f3", "type": "textarea", "label": "What in your body or the situation points to that word?"}, {"id": "f4", "type": "textarea", "label": "How intense is that feeling right now, from 0 to 10?"}]'::jsonb, array['emotion regulation', 'psychoeducation', 'core CBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('external-focus-attention-shift-sheet', 'External Focus Attention Shift Sheet', 'cbt'::resource_kind, 'Trains a client to deliberately shift attention outward instead of scanning for threat.', 'Use it to build a repeatable skill for redirecting attention away from internal threat monitoring.', array['Adults', 'Teens']::text[], '15 minutes', 'In session, have the client notice how much attention is on internal sensations or worry versus the outside world, then practice deliberately naming external details for sixty seconds while anxious. Clients often insist they cannot look away from the internal alarm; normalize the pull back inward and count each return to external focus as a rep, not a failure. Use real anxious moments between sessions as practice rounds and log how attention shifted the felt intensity, even briefly.', '[{"id": "f0", "type": "textarea", "label": "Before the practice: where is most of your attention right now, inside or outside?"}, {"id": "f1", "type": "textarea", "label": "Name five things you can see in as much detail as possible."}, {"id": "f2", "type": "textarea", "label": "After the practice: how intense does the anxious feeling feel now, 0 to 10?"}, {"id": "f3", "type": "textarea", "label": "What pulled your attention back inward, if anything?"}, {"id": "f4", "type": "textarea", "label": "When could you practice this again this week?"}]'::jsonb, array['anxiety', 'attention', 'behavioral experiment']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('hopelessness-evidence-log', 'Hopelessness Evidence Log', 'cbt'::resource_kind, 'Weighs evidence for and against a hopeless prediction across a real week.', 'Use it to test a hopeless thought against what actually happens, day by day.', array['Adults', 'Teens']::text[], 'One week', 'Have the client write down one specific hopeless prediction, such as ''nothing will get better,'' then log daily evidence that supports or complicates it. Clients often log only confirming evidence out of habit; prompt them each day for at least one small counter-example, even a minor one. Review the log together at the next session rather than letting the client score it alone, since low mood tends to discount small positives before they get written down.', '[{"id": "f0", "type": "textarea", "label": "Write the hopeless thought exactly as it shows up for you."}, {"id": "f1", "type": "textarea", "label": "Today''s evidence that supports this thought."}, {"id": "f2", "type": "textarea", "label": "Today''s evidence that complicates or contradicts this thought."}, {"id": "f3", "type": "textarea", "label": "How strongly do you believe the thought right now, 0 to 100?"}, {"id": "f4", "type": "textarea", "label": "What''s one thing you noticed today that you almost didn''t count?"}]'::jsonb, array['depression', 'core CBT', 'evidence log']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('task-switch-cost-log', 'Task-Switch Cost Log', 'cbt'::resource_kind, 'Tracks how much time and focus is lost each time a client switches tasks.', 'Use it to make the hidden cost of task-switching visible and countable.', array['Adults', 'Teens']::text[], 'One week', 'Have the client jot down every time they switch from one task to another before finishing it, noting roughly how long it took to refocus afterward. Clients often underestimate how often this happens until they see it logged over a few days. Review the log together looking for patterns, such as a specific time of day or a specific trigger like a notification, and use it to pick one switching point worth experimenting with first rather than trying to fix all of them at once.', '[{"id": "f0", "type": "textarea", "label": "What task were you working on before the switch?"}, {"id": "f1", "type": "textarea", "label": "What pulled your attention away?"}, {"id": "f2", "type": "textarea", "label": "About how long did it take to get back to the first task?"}, {"id": "f3", "type": "textarea", "label": "What time of day did this happen?"}, {"id": "f4", "type": "textarea", "label": "Which switching point would you like to experiment with first?"}]'::jsonb, array['ADHD', 'self-monitoring', 'executive function']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('anger-intensity-reality-check', 'Anger Intensity Reality Check', 'cbt'::resource_kind, 'Compares a client''s in-the-moment anger rating to the situation''s actual stakes.', 'Use it to recalibrate anger intensity ratings against the actual size of the situation.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client rate how angry a recent situation made them feel, then separately rate how big a deal the situation actually was on the same scale, and compare the gap. A wide gap is the useful finding, not a reason for the client to feel bad; use it to explore what inflated the rating, such as a past pattern or an assumption about intent. Repeat across a few situations to look for a consistent gap size, which can become an early cue the client learns to catch mid-episode.', '[{"id": "f0", "type": "textarea", "label": "Describe the situation briefly."}, {"id": "f1", "type": "textarea", "label": "How angry did you feel, 0 to 10?"}, {"id": "f2", "type": "textarea", "label": "How big a deal was the situation actually, 0 to 10?"}, {"id": "f3", "type": "textarea", "label": "What might explain the gap between the two numbers?"}, {"id": "f4", "type": "textarea", "label": "What could remind you to check this gap in the moment?"}]'::jsonb, array['anger management', 'core CBT', 'self-monitoring']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('mental-compulsion-spotting-guide', 'Mental Compulsion Spotting Guide', 'cbt'::resource_kind, 'Helps someone tell silent mental rituals apart from ordinary thinking.', 'Use it to catch mental reviewing, counting, or rewording hiding as thoughts.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through this checklist of common mental rituals with the client, since many people don''t realize replaying a conversation, silently repeating a phrase, or mentally reviewing an action is a compulsion rather than just thinking; do the first pass together in session, because spotting the pattern often takes a second set of eyes before the client can catch it on their own.', '[{"id": "f0", "type": "textarea", "label": "I replay a conversation in my head until it feels right."}, {"id": "f1", "type": "textarea", "label": "I silently repeat a word or phrase to myself."}, {"id": "f2", "type": "textarea", "label": "I mentally review what I did to check I did it correctly."}, {"id": "f3", "type": "textarea", "label": "I count in my head until reaching a certain number."}, {"id": "f4", "type": "textarea", "label": "I mentally cancel out a bad thought with a good one."}]'::jsonb, array['OCD', 'psychoeducation', 'mental rituals']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('intentional-misbehavior-attribution-check', 'Intentional Misbehavior Attribution Check', 'cbt'::resource_kind, 'Tests the automatic thought that a child is misbehaving on purpose.', 'Use it to separate what a child did from why the parent assumes they did it.', array['Adults']::text[], '15 minutes', 'Have the parent record an incident, the intention they assumed behind it, and at least one other plausible explanation such as tiredness, a developmental stage, or limit-testing, then imagine how they would have reacted believing the other explanation instead; watch for a parent who resists any explanation that doesn''t involve deliberate blame.', '[{"id": "f0", "type": "textarea", "label": "What did my child do?"}, {"id": "f1", "type": "textarea", "label": "What did I assume it meant about their intentions toward me?"}, {"id": "f2", "type": "textarea", "label": "What is another explanation, even if it''s less satisfying?"}, {"id": "f3", "type": "textarea", "label": "How would I have responded if I believed the other explanation?"}]'::jsonb, array['parenting', 'automatic thoughts', 'cognitive flexibility']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('postpartum-social-comparison-log', 'Postpartum Social Comparison Log', 'cbt'::resource_kind, 'Catches thoughts sparked by comparing a hard day to someone else''s highlight reel.', 'Use it to test comparison thoughts against what a new parent can actually know.', array['Adults']::text[], '15 minutes', 'Have the client log the comparison moment, often while scrolling, the thought about their own adequacy that followed, and what they genuinely cannot know about the other person''s day; reducing exposure to the trigger is a fair option to raise too, not just challenging the thought, and watch for the log itself becoming another reason to keep dwelling on the images.', '[{"id": "f0", "type": "textarea", "label": "What did I see or compare myself to?"}, {"id": "f1", "type": "textarea", "label": "What did I think about myself in that moment?"}, {"id": "f2", "type": "textarea", "label": "What don''t I actually know about their day?"}, {"id": "f3", "type": "textarea", "label": "What would I say to a friend who had this same thought?"}]'::jsonb, array['perinatal and postpartum', 'social comparison', 'automatic thoughts']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('discounting-the-positive-catch-sheet', 'Discounting the Positive Catch Sheet', 'cbt'::resource_kind, 'Catches the moment someone waves off a compliment or a win as not counting.', 'Use it to interrupt the habit of dismissing positive evidence about oneself.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client log a moment they brushed off good feedback or an accomplishment, the exact phrase they used to make it not count, such as anyone could have done that, and what a more balanced read of the same event would sound like; watch for the client agreeing with the balanced read intellectually while still not letting the credit actually land.', '[{"id": "f0", "type": "textarea", "label": "What positive thing happened or was said to me?"}, {"id": "f1", "type": "textarea", "label": "What did I tell myself right after, to make it not count?"}, {"id": "f2", "type": "textarea", "label": "What would I say if a friend dismissed the same thing about themselves?"}, {"id": "f3", "type": "textarea", "label": "What is a more balanced read of what happened?"}]'::jsonb, array['self-esteem', 'thinking traps', 'automatic thoughts']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('meaning-reconstruction-log', 'Meaning Reconstruction Log', 'cbt'::resource_kind, 'Tracks small moments where a client makes new sense of life after a loss.', 'Use it to help a client notice meaning forming alongside grief, not instead of it.', array['Adults']::text[], 'One week', 'Give this to a client several weeks into grieving, once acute waves have started to space out, to log moments — even brief ones — where they find a new way of understanding their loss or their life without the person. This is not about arriving at a tidy silver lining; some entries may stay unresolved, and that is fine. Clients sometimes worry that finding any meaning means the loss did not matter, so name that tension directly and let the log hold both grief and growth side by side.', '[{"id": "f0", "type": "textarea", "label": "Today I noticed this small moment of understanding or meaning…"}, {"id": "f1", "type": "textarea", "label": "What this moment tells me about how I''m making sense of the loss…"}, {"id": "f2", "type": "textarea", "label": "A thought I had that still doesn''t make sense to me…"}, {"id": "f3", "type": "textarea", "label": "Something I believe differently now than before this loss…"}, {"id": "f4", "type": "textarea", "label": "A way I''ve honored or carried forward something from the person or thing I lost…"}]'::jsonb, array['grief and loss', 'meaning making', 'core CBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('unmet-expectations-cost-benefit-sheet', 'Unmet Expectations Cost-Benefit Sheet', 'cbt'::resource_kind, 'Weighs the cost and benefit of holding on to an unspoken expectation of a partner.', 'Use it to help a client decide whether to voice, adjust, or release an expectation.', array['Adults']::text[], '20 minutes', 'Use this when a client is quietly resentful about an expectation of their partner that was never actually stated out loud. Have them name the expectation, then list what holding onto it silently costs them and what, if anything, it gets them, followed by the same two columns for voicing it directly instead. Clients often discover the silent version costs more than they realized once it''s written down side by side. This works well paired with a plan for how and when to actually voice the expectation, which the clinician can build with the client separately.', '[{"id": "f0", "type": "textarea", "label": "The expectation of my partner I''ve never said out loud…"}, {"id": "f1", "type": "textarea", "label": "What staying silent about it costs me…"}, {"id": "f2", "type": "textarea", "label": "What staying silent about it gets me, if anything…"}, {"id": "f3", "type": "textarea", "label": "What voicing it directly might cost me…"}, {"id": "f4", "type": "textarea", "label": "What voicing it directly might get me…"}, {"id": "f5", "type": "textarea", "label": "What I want to do with this expectation now…"}]'::jsonb, array['relationship issues', 'core CBT', 'unmet expectations']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('nothing-helps-belief-check', 'Nothing Helps Belief Check', 'cbt'::resource_kind, 'Gathers evidence against the thought that no coping skill ever works.', 'Use it to test the all-or-nothing belief that coping skills are pointless.', array['Adults']::text[], '20 minutes', 'Use this when a client dismisses coping skills work with a blanket thought like ''nothing helps anyway.'' Write the thought down, then go skill by skill through ones they have tried, rating how much each one helped on a 0 to 10 scale rather than a pass-or-fail. Most clients find at least partial relief somewhere once they are asked to rate rather than judge; the point is loosening the all-or-nothing belief, not proving every skill works perfectly. Watch for a client who rates everything a zero reflexively — slow down and ask about a specific recent moment instead of a general impression.', '[{"id": "f0", "type": "textarea", "label": "The thought I have about coping skills in general…"}, {"id": "f1", "type": "textarea", "label": "A skill I''ve tried: how much did it help, 0 to 10…"}, {"id": "f2", "type": "textarea", "label": "A second skill I''ve tried: how much did it help, 0 to 10…"}, {"id": "f3", "type": "textarea", "label": "A third skill I''ve tried: how much did it help, 0 to 10…"}, {"id": "f4", "type": "textarea", "label": "What I notice about the belief now that I''ve rated these…"}]'::jsonb, array['coping skills', 'core CBT', 'evidence log']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('predicted-vs-actual-fear-outcome-log', 'Predicted vs Actual Fear Outcome Log', 'cbt'::resource_kind, 'Compares a client''s predicted worst outcome to what actually happened after facing a fear.', 'Use it to build evidence against overestimated danger from a specific feared object.', array['Adults', 'Teens']::text[], '20 minutes', 'Before an approach step, have the client write down their specific predicted outcome and how certain they feel about it, then fill in what actually happened right after. Repeating this across several approach steps builds a running record the client can review when facing the next one, which tends to land better than a single conversation about probability. Watch for predictions written vaguely enough to always seem ''sort of'' true; push for a specific, checkable prediction each time.', '[{"id": "f0", "type": "textarea", "label": "The feared object or situation I''m approaching…"}, {"id": "f1", "type": "textarea", "label": "My specific predicted outcome…"}, {"id": "f2", "type": "textarea", "label": "How certain I am this will happen, 0 to 100%…"}, {"id": "f3", "type": "textarea", "label": "What actually happened…"}, {"id": "f4", "type": "textarea", "label": "How certain I am now for next time…"}]'::jsonb, array['phobias', 'core CBT', 'behavioral experiment']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('before-and-after-scrolling-belief-test', 'Before and After Scrolling Belief Test', 'cbt'::resource_kind, 'Tests a client''s prediction about mood before and after a specific stretch of scrolling.', 'Use it to test whether a block of social media time changes mood the way a client expects.', array['Adults', 'Teens']::text[], '20 minutes', 'Before the client opens a social media app for a set block of time, have them write a specific prediction about how they''ll feel about their own appearance afterward, and how confident they are in it. Right after, they rate their actual mood and appearance-related thoughts and compare the two. Repeating this across a few apps or accounts often shows some sources reliably worsen mood while others barely register, which lands better than a general talk about screen habits. Watch for vague predictions; push for a specific, checkable one each time.', '[{"id": "f0", "type": "textarea", "label": "The app or account and time block I''m about to scroll through…"}, {"id": "f1", "type": "textarea", "label": "My prediction: how will I feel about my appearance afterward…"}, {"id": "f2", "type": "textarea", "label": "How confident I am in that prediction, 0 to 100%…"}, {"id": "f3", "type": "textarea", "label": "What I actually felt afterward…"}, {"id": "f4", "type": "textarea", "label": "What I noticed comparing the two…"}]'::jsonb, array['body image', 'core CBT', 'behavioral experiment']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('80th-birthday-toast-practice', '80th Birthday Toast Practice', 'act'::resource_kind, 'A guided imagery exercise where a client imagines the toast given at their 80th birthday.', 'Use it to surface a client''s values by imagining how they''d want to be remembered.', array['Adults', 'Teens']::text[], '20 minutes', 'Guide the client to imagine sitting at their own 80th birthday party, listening to someone who knows them well give a toast, and have them write what they''d genuinely want that toast to say. Clients sometimes write what they think they should want rather than what they actually value; ask them to notice if any line feels borrowed from someone else''s expectations. Use the toast to name two or three values to build committed action around.', '[{"id": "f0", "type": "textarea", "label": "Who is giving the toast, and what is your relationship to them?"}, {"id": "f1", "type": "textarea", "label": "What do you most want them to say about how you treated people?"}, {"id": "f2", "type": "textarea", "label": "What do you want them to say about what you did with your time?"}, {"id": "f3", "type": "textarea", "label": "Read your toast back: does any line feel borrowed rather than yours?"}, {"id": "f4", "type": "textarea", "label": "What value shows up most clearly in what you wrote?"}]'::jsonb, array['values', 'core ACT', 'life review']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('sing-the-thought-defusion-exercise', 'Sing the Thought Defusion Exercise', 'act'::resource_kind, 'A playful defusion exercise where a client sings a sticky thought to a familiar tune.', 'Use it to loosen the grip of a sticky thought by changing how it''s delivered.', array['Adults', 'Teens']::text[], 'Ten minutes', 'In session, have the client say a sticky thought out loud in their normal voice, then sing the exact same words to a familiar tune like Happy Birthday, and notice what shifts. Some clients feel silly and rush through it; slow them down and ask what changed about the thought''s weight, not just whether it was funny. This works best as an in-session demonstration before asking a client to try it on their own between sessions.', '[{"id": "f0", "type": "textarea", "label": "Say the sticky thought out loud, in your normal voice."}, {"id": "f1", "type": "textarea", "label": "Now sing the same words to a tune you know well."}, {"id": "f2", "type": "textarea", "label": "What changed about how the thought felt?"}, {"id": "f3", "type": "textarea", "label": "Did the thought''s content change, or just how it landed?"}, {"id": "f4", "type": "textarea", "label": "When this week could you try this with a thought that shows up?"}]'::jsonb, array['defusion', 'core ACT', 'mindfulness']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('values-implementation-intentions-sheet', 'Values Implementation Intentions Sheet', 'act'::resource_kind, 'A worksheet that turns a value into a specific if-then plan for the coming week.', 'Use it to close the gap between naming a value and actually acting on it.', array['Adults', 'Teens']::text[], '20 minutes', 'The client picks one value and writes a specific if-then plan: when a named situation comes up this week, they will take a named action in line with that value. Clients often write the value side clearly but leave the action vague, such as be more present; push for something observable enough that another person could see them do it. Review the plan next session and troubleshoot whichever part, the trigger or the action, didn''t hold up.', '[{"id": "f0", "type": "textarea", "label": "Which value do you want to bring into this week?"}, {"id": "f1", "type": "textarea", "label": "What situation is likely to come up where this value matters?"}, {"id": "f2", "type": "textarea", "label": "Finish this: If [situation], then I will [specific action]."}, {"id": "f3", "type": "textarea", "label": "What might get in the way of following through?"}, {"id": "f4", "type": "textarea", "label": "How will you know, afterward, that you did it?"}]'::jsonb, array['values', 'committed action', 'goal setting']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('raisin-mindfulness-exercise', 'Raisin Mindfulness Exercise', 'act'::resource_kind, 'A slow, sense-by-sense exercise of noticing a small piece of food before eating it.', 'Use it to give a client a first, concrete taste of present-moment noticing.', array['Adults', 'Teens', 'Groups']::text[], 'Ten minutes', 'Hand the client a raisin or another small piece of food and walk them through noticing its look, texture, and smell before slowly eating it, pausing at each step. Clients often eat quickly out of habit before the exercise gets going, so name that upfront as the very thing you''re practicing noticing. Debrief by asking what they noticed that they wouldn''t have on a normal day, and connect that to bringing the same noticing to a daily routine of their choosing.', '[{"id": "f0", "type": "textarea", "label": "Before eating, describe how it looks and feels in your hand."}, {"id": "f1", "type": "textarea", "label": "What do you notice about its smell?"}, {"id": "f2", "type": "textarea", "label": "Eat it slowly. What do you notice about the first taste?"}, {"id": "f3", "type": "textarea", "label": "Did you catch yourself wanting to rush? When?"}, {"id": "f4", "type": "textarea", "label": "What''s one daily moment you could bring this same noticing to?"}]'::jsonb, array['mindfulness', 'present moment', 'core ACT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('act-matrix-worksheet', 'ACT Matrix Worksheet', 'act'::resource_kind, 'A four-quadrant diagram sorting a client''s inner experience from their toward and away moves.', 'Use it to map the difference between moving toward values and moving away from discomfort.', array['Adults', 'Teens']::text[], 'Full session', 'Draw the two crossing lines of the matrix with the client: one axis for what shows up inside versus what shows up in the world, the other for moves away from discomfort versus moves toward what matters. Sort recent behaviors into the four quadrants together, and expect early confusion between toward and away moves that look similar from the outside but feel different on the inside. The finished matrix becomes a quick check-in tool for later sessions.', '[{"id": "f0", "type": "textarea", "label": "What thoughts, feelings or sensations show up that you''d rather not have?"}, {"id": "f1", "type": "textarea", "label": "What do you do to get away from those, in the moment?"}, {"id": "f2", "type": "textarea", "label": "Who and what matters to you, even when it''s hard?"}, {"id": "f3", "type": "textarea", "label": "What would you do more of if you were moving toward that?"}, {"id": "f4", "type": "textarea", "label": "Looking at your four quadrants, which move shows up most often?"}]'::jsonb, array['ACT Matrix', 'values', 'committed action']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('safe-distance-observer-practice', 'Safe Distance Observer Practice', 'act'::resource_kind, 'Helps a client step back and watch triggered thoughts and body sensations from a safe distance.', 'Use it to build a felt sense of distance from triggered thoughts and sensations.', array['Adults', 'Teens']::text[], '15 minutes', 'Guide the client to notice a triggered thought or sensation, then imagine watching it from a step back, as if seated in a different chair, while both feet stay planted on the floor. People often try to push the sensation away instead of just watching it; gently redirect back to noticing without judging. Stop and ground with breath or feet-on-floor contact if activation climbs, and never use this to explore or narrate what happened, only what is happening in the room right now.', '[{"id": "f0", "type": "textarea", "label": "What thought or sensation showed up just now?"}, {"id": "f1", "type": "textarea", "label": "If you took a step back and just watched it, what do you notice?"}, {"id": "f2", "type": "textarea", "label": "What do your feet feel like on the floor right now?"}, {"id": "f3", "type": "textarea", "label": "On a scale of 1 to 10, how activated do you feel right now?"}, {"id": "f4", "type": "textarea", "label": "What is one thing in this room you can see, right now?"}]'::jsonb, array['PTSD and trauma', 'grounding', 'defusion', 'self-as-context']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('acting-alongside-the-fog-practice', 'Acting Alongside the Fog Practice', 'act'::resource_kind, 'Guides a client to take one values-based step while low mood is still present.', 'Use it to practice moving with depression''s fog instead of waiting for it to clear.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to name a mental fog or heaviness that shows up with low mood, then pick one small values-aligned action to take alongside it rather than after it lifts. Clients often make waiting for the fog to clear a precondition for acting; use this practice to separate the feeling from the doing. Keep the chosen action genuinely small, and afterward ask what changed and what stayed exactly the same, since the fog not lifting is an expected, workable outcome here, not a failure of the exercise.', '[{"id": "f0", "type": "textarea", "label": "Describe the fog or heaviness in your own words."}, {"id": "f1", "type": "textarea", "label": "Name one small action that matters to you, regardless of the fog."}, {"id": "f2", "type": "textarea", "label": "What did you do, alongside the fog, today?"}, {"id": "f3", "type": "textarea", "label": "What changed after you acted? What stayed the same?"}, {"id": "f4", "type": "textarea", "label": "Was waiting for the fog to lift part of your plan? What if it wasn''t required?"}]'::jsonb, array['depression', 'values', 'core ACT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('boredom-willingness-practice-for-tasks', 'Boredom Willingness Practice for Tasks', 'act'::resource_kind, 'Builds willingness to sit with boredom during a low-stimulation task.', 'Use it to build tolerance for boredom without needing to escape the task.', array['Adults', 'Teens']::text[], '10 minutes', 'Have the client pick one genuinely boring but necessary task and practice noticing the urge to escape it as a physical sensation rather than acting on it right away, timing how long they can stay willing to feel bored before taking a planned break. Clients often frame boredom as unbearable rather than uncomfortable; help them separate the two. Keep the timed stretch short enough to succeed, then gradually extend it session over session, treating each willing minute as the actual goal rather than how much of the task got finished.', '[{"id": "f0", "type": "textarea", "label": "What task are you practicing with today?"}, {"id": "f1", "type": "textarea", "label": "Where do you feel the urge to escape boredom in your body?"}, {"id": "f2", "type": "textarea", "label": "How many minutes were you willing to stay with it?"}, {"id": "f3", "type": "textarea", "label": "What did you do instead of acting on the urge to switch?"}, {"id": "f4", "type": "textarea", "label": "What would a slightly longer stretch look like next time?"}]'::jsonb, array['ADHD', 'willingness', 'core ACT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('anger-messenger-defusion-practice', 'Anger Messenger Defusion Practice', 'act'::resource_kind, 'Frames an angry thought as a messenger to notice, not an order to follow.', 'Use it to create space between an angry thought and the action it''s pushing for.', array['Adults', 'Teens']::text[], '15 minutes', 'When an angry thought shows up, have the client say it in the form ''my mind is delivering the message that...'' and then ask what the message wants them to do right now. Clients often fuse the message with a command they must obey immediately; practice noticing the gap between hearing the message and choosing the action. Once there''s space, check the wanted action against what actually matters to the client in that relationship or moment, and pick from there rather than from the message alone.', '[{"id": "f0", "type": "textarea", "label": "What is the angry thought, word for word?"}, {"id": "f1", "type": "textarea", "label": "Say it as ''my mind is delivering the message that...'' What message is it?"}, {"id": "f2", "type": "textarea", "label": "What action is the message pushing you toward?"}, {"id": "f3", "type": "textarea", "label": "What actually matters to you in this moment or relationship?"}, {"id": "f4", "type": "textarea", "label": "What will you choose to do, having heard the message?"}]'::jsonb, array['anger management', 'defusion', 'core ACT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('doubt-surfing-practice', 'Doubt Surfing Practice', 'act'::resource_kind, 'Guides someone to ride out a wave of doubt instead of resolving it.', 'Use it to build tolerance for doubt without checking, asking, or reviewing.', array['Adults', 'Teens']::text[], '10 minutes', 'Modeled on urge surfing, this has the client notice the pull to seek certainty, rate how strong it feels, and simply watch it rise and fall without acting on it; most people expect the pull to keep climbing forever, so the surprise is usually how much it drops within a few minutes once no ritual follows it.', '[{"id": "f0", "type": "textarea", "label": "What is the doubt telling me I need to check or confirm?"}, {"id": "f1", "type": "textarea", "label": "Rate the pull to resolve it right now, zero to ten."}, {"id": "f2", "type": "textarea", "label": "Where do I feel it in my body?"}, {"id": "f3", "type": "textarea", "label": "What happens to the pull after a few minutes if I don''t act on it?"}, {"id": "f4", "type": "textarea", "label": "What did I do instead of chasing certainty?"}]'::jsonb, array['OCD', 'uncertainty', 'willingness']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('panic-committed-action-bridge', 'Panic Committed Action Bridge', 'act'::resource_kind, 'Plans one values-based action to take even while fearing another panic attack.', 'Use it to keep life moving forward between panic episodes, not around them.', array['Adults', 'Teens']::text[], '20 minutes', 'Use this after the acute fear has settled, not during an episode, to identify an activity the client has been avoiding, connect it to something that matters to them, and break it into a step small enough to actually attempt this week; watch for a step chosen so small it never really tests the avoidance.', '[{"id": "f0", "type": "textarea", "label": "What have I been putting off because I''m afraid of having another panic attack?"}, {"id": "f1", "type": "textarea", "label": "What does doing this connect to that matters to me?"}, {"id": "f2", "type": "textarea", "label": "What is one step small enough to try this week?"}, {"id": "f3", "type": "textarea", "label": "What will I do if a panic attack starts while I''m doing it?"}]'::jsonb, array['panic attacks', 'committed action', 'values']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('holding-both-selves-practice', 'Holding Both Selves Practice', 'act'::resource_kind, 'Helps a new parent hold their old identity and new role side by side.', 'Use it to loosen the either/or pull between who someone was and who they are now.', array['Adults']::text[], '15 minutes', 'Have the client list parts of their pre-baby self they miss alongside parts of new-parent life they are starting to value, then practice language of both rather than framing it as who they used to be versus who they are now; resist reassuring them their old self is still fully intact, and watch for this sliding into grief work that needs more room than one exercise allows.', '[{"id": "f0", "type": "textarea", "label": "Something about who I was before that I still value."}, {"id": "f1", "type": "textarea", "label": "Something about being a parent that I''m starting to value."}, {"id": "f2", "type": "textarea", "label": "Can both of these be true about me right now?"}, {"id": "f3", "type": "textarea", "label": "What is one small way to make room for the old self this week?"}]'::jsonb, array['perinatal and postpartum', 'self-as-context', 'values']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('achievements-aside-self-practice', 'Achievements Aside Self Practice', 'act'::resource_kind, 'Separates a sense of worth from the day''s list of wins and failures.', 'Use it to practice a sense of self that doesn''t rise and fall with performance.', array['Adults', 'Teens']::text[], '10 minutes', 'Have the client set today''s wins and failures aside on paper and notice what, if anything, remains true about them either way; this is a self-as-context exercise rather than a pep talk, so resist reassuring the client their achievements are actually good, and watch for it being used to dismiss real accomplishments instead of decoupling worth from them.', '[{"id": "f0", "type": "textarea", "label": "List today''s wins and today''s failures."}, {"id": "f1", "type": "textarea", "label": "Set the list aside. What is still true about me either way?"}, {"id": "f2", "type": "textarea", "label": "What does it feel like to imagine worth that isn''t earned or lost?"}, {"id": "f3", "type": "textarea", "label": "What is one moment today I can practice this?"}]'::jsonb, array['self-esteem', 'self-as-context', 'core ACT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('should-be-over-it-by-now-defusion-practice', 'Should Be Over It by Now Defusion Practice', 'act'::resource_kind, 'Defuses from judgmental thoughts about how a client ''should'' be grieving.', 'Use it to loosen the grip of timeline judgments a client makes about their own grief.', array['Adults']::text[], '15 minutes', 'Use this when a client criticizes themselves for still grieving, comparing their pace to some imagined timeline. Have them say the judgmental thought aloud, then add the defusion frame (''I''m having the thought that I should be over this by now'') and notice what shifts in how much the thought pulls at them. Some clients resist the exercise because it can feel like permission to stay stuck; clarify that defusion loosens the thought''s grip, it does not endorse or argue with it. Watch for a client who intellectualizes the practice instead of actually trying it out loud.', '[{"id": "f0", "type": "textarea", "label": "The judgmental thought about my grief timeline, in my own words…"}, {"id": "f1", "type": "textarea", "label": "Now with ''I''m having the thought that...'' in front of it…"}, {"id": "f2", "type": "textarea", "label": "What I notice in my body saying it that way…"}, {"id": "f3", "type": "textarea", "label": "How much this thought pulled at me before, 0 to 10…"}, {"id": "f4", "type": "textarea", "label": "How much it pulls at me now, 0 to 10…"}]'::jsonb, array['grief and loss', 'defusion', 'core ACT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('needing-to-win-defusion-practice', 'Needing to Win Defusion Practice', 'act'::resource_kind, 'Defuses from the urge to win an argument instead of staying connected.', 'Use it to help a client notice the pull to be right and choose a value-driven response instead.', array['Adults', 'Couples']::text[], '15 minutes', 'Bring this out after a client describes an argument they ''won'' but that left the relationship worse off. Have them name the thought driving the fight (''I have to make them admit I''m right''), then practice noticing it as a thought passing through rather than a command to obey, and ask what mattered more in that moment — winning or staying connected. Clients who pride themselves on debate skill may resist this, framing defusion as giving up ground; reframe it as choosing which fight is worth having. Watch for the exercise turning into another way to feel superior to the partner.', '[{"id": "f0", "type": "textarea", "label": "The argument where I really wanted to win…"}, {"id": "f1", "type": "textarea", "label": "The thought that was driving me to win…"}, {"id": "f2", "type": "textarea", "label": "Saying ''I''m noticing the thought that I need to win this''…"}, {"id": "f3", "type": "textarea", "label": "What I actually wanted from this argument underneath winning…"}, {"id": "f4", "type": "textarea", "label": "What I''d choose to do next time this thought shows up…"}]'::jsonb, array['relationship issues', 'defusion', 'core ACT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('observing-self-safety-practice', 'Observing Self Safety Practice', 'act'::resource_kind, 'Uses an observing-self stance to notice body alarm signals from a safe distance.', 'Use it to help a client notice body signals in the present without being swept into them.', array['Adults', 'Teens']::text[], '15 minutes', 'Run this in session when a client''s body reacts strongly to something in the here and now — a sound, a posture, a smell — and they feel pulled into the sensation rather than simply having it. Guide them to notice the sensation from the stance of an observer watching it happen, naming it without narrating any past event: what the body is doing right now, in this room, today. This stays entirely present-focused, never a place to describe what happened. If a client starts recounting past details, gently redirect back to present sensations and the safety of the current room.', '[{"id": "f0", "type": "textarea", "label": "The sensation I''m noticing in my body right now…"}, {"id": "f1", "type": "textarea", "label": "Where in my body I notice it most…"}, {"id": "f2", "type": "textarea", "label": "From the observer part of me, what I see this sensation doing…"}, {"id": "f3", "type": "textarea", "label": "One thing in this room right now that tells me I''m safe…"}, {"id": "f4", "type": "textarea", "label": "How the sensation is different now than when we started…"}]'::jsonb, array['sexual abuse', 'grounding', 'self-as-context']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('cant-handle-it-defusion-practice', 'Can''t Handle It Defusion Practice', 'act'::resource_kind, 'Defuses from the thought that a client can''t handle being near a feared object.', 'Use it to loosen a client''s belief that fear itself is proof they can''t cope.', array['Adults', 'Teens']::text[], '15 minutes', 'Use this right before or during an approach step when a client says something like ''I can''t handle this'' as their fear rises. Have them notice the thought, add the defusion frame (''I''m having the thought that I can''t handle this''), then check what''s actually happening in their body and the room right now, separate from the thought''s prediction. This isn''t about proving the thought wrong through argument; it''s about taking a step with the thought present rather than waiting for it to vanish first. Watch for a client who uses defusion as a stalling tactic instead of continuing the step.', '[{"id": "f0", "type": "textarea", "label": "The situation where this thought shows up…"}, {"id": "f1", "type": "textarea", "label": "The thought in its original form…"}, {"id": "f2", "type": "textarea", "label": "The thought with ''I''m having the thought that...'' added…"}, {"id": "f3", "type": "textarea", "label": "What''s actually true in this room right now, separate from the thought…"}, {"id": "f4", "type": "textarea", "label": "What I can do next with the thought still present…"}]'::jsonb, array['phobias', 'defusion', 'core ACT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('checking-urge-surf-and-defuse-practice', 'Checking Urge Surf and Defuse Practice', 'act'::resource_kind, 'Rides out the urge to mirror-check or compare instead of acting on it right away.', 'Use it to help a client notice a checking urge pass without acting on it every time.', array['Adults', 'Teens']::text[], '15 minutes', 'Use this when a client notices the pull to check a mirror, photo, or reflection repeatedly through the day. Have them pause when the urge hits, name it out loud as an urge rather than a need, and time how long it takes to ease off while doing something else. Most urges peak and fall within a few minutes if not acted on, and clients rarely expect that. Watch for a client who checks once as an experiment and calls the practice a failure — the goal is noticing the urge pass, not eliminating checking overnight.', '[{"id": "f0", "type": "textarea", "label": "Where I am and what triggered the urge to check…"}, {"id": "f1", "type": "textarea", "label": "Rating the urge to check, 0 to 10, right when it starts…"}, {"id": "f2", "type": "textarea", "label": "What I did instead of checking…"}, {"id": "f3", "type": "textarea", "label": "The urge rating after a few minutes…"}, {"id": "f4", "type": "textarea", "label": "What I noticed about how the urge changed…"}]'::jsonb, array['body image', 'urges', 'core ACT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('cheerleading-statements-card', 'Cheerleading Statements Card', 'dbt'::resource_kind, 'A pocket card of self-encouraging statements a client rehearses before a hard moment.', 'Use it to replace a client''s harsh self-talk with statements they can actually believe.', array['Adults', 'Teens']::text[], '15 minutes', 'The client writes several short, believable self-encouraging statements, such as I can do this one step at a time rather than an empty everything is fine, and picks the situations where they''ll use them. Clients often reach for statements that are too rosy to trust in the moment, which backfires; steer them toward something true enough to hold up under stress. Have them read the card out loud in session and notice which lines land and which still feel hollow.', '[{"id": "f0", "type": "textarea", "label": "Write three statements you could actually believe when things get hard."}, {"id": "f1", "type": "textarea", "label": "Which one feels most believable right now?"}, {"id": "f2", "type": "textarea", "label": "What situation this week could you use this card in?"}, {"id": "f3", "type": "textarea", "label": "Read each statement out loud. Which one feels hollow?"}, {"id": "f4", "type": "textarea", "label": "Rewrite any that feel hollow into something truer."}]'::jsonb, array['self-talk', 'core DBT', 'motivation']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('one-mindfully-focus-practice', 'One-Mindfully Focus Practice', 'dbt'::resource_kind, 'A short practice of doing exactly one thing at a time and noticing the pull to multitask.', 'Use it to build a client''s capacity to stay with one task without splitting attention.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Pick one everyday task with the client, washing a dish or walking to the mailbox, and have them do only that, bringing attention back each time it drifts to something else. Clients usually notice the pull to multitask within seconds and treat it as failure; reframe each return of attention as the actual practice, not a sign it isn''t working. Build up from one task a day to a few, and log what pulled attention away most often.', '[{"id": "f0", "type": "textarea", "label": "What one task will you do one-mindfully today?"}, {"id": "f1", "type": "textarea", "label": "How many times did your attention drift during the task?"}, {"id": "f2", "type": "textarea", "label": "What pulled your attention away?"}, {"id": "f3", "type": "textarea", "label": "What did you notice about the task itself when you stayed with it?"}, {"id": "f4", "type": "textarea", "label": "What task will you try this with tomorrow?"}]'::jsonb, array['mindfulness', 'core DBT', 'habits']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('acceptance-and-change-goal-planner', 'Acceptance and Change Goal Planner', 'dbt'::resource_kind, 'A goal sheet that pairs each goal with one thing to accept alongside it.', 'Use it to help a client hold acceptance and change side by side instead of choosing one.', array['Adults', 'Teens']::text[], '20 minutes', 'For each goal the client sets, they also name one part of the current situation they need to accept as true right now in order to work toward it without being derailed by wishing things were already different. Clients often resist the acceptance side, treating it as giving up; clarify that accepting what''s currently true is what frees up energy for the change itself. Revisit both columns together at each check-in.', '[{"id": "f0", "type": "textarea", "label": "What''s one goal you want to work toward?"}, {"id": "f1", "type": "textarea", "label": "What''s currently true that you''d need to accept to work toward it calmly?"}, {"id": "f2", "type": "textarea", "label": "What''s one small step toward the goal this week?"}, {"id": "f3", "type": "textarea", "label": "What tends to happen when you fight the thing you need to accept?"}, {"id": "f4", "type": "textarea", "label": "How will accepting it change what you do differently?"}]'::jsonb, array['goal setting', 'dialectics', 'core DBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('mindful-pause-bell-practice', 'Mindful Pause Bell Practice', 'dbt'::resource_kind, 'A practice of pausing whenever a bell or cue sounds to notice the present moment.', 'Use it to build a habit of brief mindful pauses scattered through an ordinary day.', array['Adults', 'Teens']::text[], 'Five minutes daily for several weeks', 'The client picks a recurring cue already in their day, a phone alarm, a red light, a kettle, and pauses for three slow breaths and a quick body scan whenever it happens, logging what they noticed. The most common trip-up is picking a cue that''s too rare to build the habit, or forgetting the log entirely; a cue that happens several times a day works best. Use the log to spot which times of day the client is most scattered.', '[{"id": "f0", "type": "textarea", "label": "What cue will you use to trigger your pause?"}, {"id": "f1", "type": "textarea", "label": "Each time it happens, what did you notice in your body?"}, {"id": "f2", "type": "textarea", "label": "What were you doing right before the cue went off?"}, {"id": "f3", "type": "textarea", "label": "How many pauses did you catch today?"}, {"id": "f4", "type": "textarea", "label": "What time of day were you hardest to pause?"}]'::jsonb, array['mindfulness', 'core DBT', 'session structure']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('alternate-rebellion-idea-bank', 'Alternate Rebellion Idea Bank', 'dbt'::resource_kind, 'A list of small, harmless rule-breaks a client can use instead of a riskier one.', 'Use it to give a client a safer outlet for the urge to break a rule or push back.', array['Adults', 'Teens']::text[], '20 minutes', 'The client brainstorms small, harmless ways to scratch the itch of rebelling, wearing mismatched socks, taking a different route home, staying up late reading, to have on hand when the urge to break a bigger rule shows up. Clients sometimes can''t tell the difference between an urge to rebel and an urge tied to something else entirely, like anger or boredom; help them sort the list by what the urge is actually about. Keep the bank updated as old ideas lose their charge.', '[{"id": "f0", "type": "textarea", "label": "What rule or expectation do you feel the urge to push back against?"}, {"id": "f1", "type": "textarea", "label": "List five small, harmless ways you could rebel instead."}, {"id": "f2", "type": "textarea", "label": "Which one could you use the next time the urge shows up?"}, {"id": "f3", "type": "textarea", "label": "What is the urge actually about underneath the rebellion?"}, {"id": "f4", "type": "textarea", "label": "How did it go the last time you tried one of these?"}]'::jsonb, array['distress tolerance', 'core DBT', 'habits']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('wise-mind-anchor-phrase-card', 'Wise Mind Anchor Phrase Card', 'dbt'::resource_kind, 'Gives a client a short wise mind phrase to repeat when a trauma reminder spikes arousal.', 'Use it to build a fast, portable anchor for moments of high activation.', array['Adults', 'Teens']::text[], '10 minutes', 'In session, help the client craft one short phrase that names the present moment as safe enough right now, such as ''that was then, this is now, I am here.'' Write it on a card they can keep in a pocket or phone. People often reach for a long explanation instead of a short phrase; keep it to one breath''s worth of words. Practice saying it out loud together while the client notices their feet or hands, and check that the wording feels true rather than forced before they leave with it.', '[{"id": "f0", "type": "textarea", "label": "Write your anchor phrase in your own words."}, {"id": "f1", "type": "textarea", "label": "Where will you keep this card so it''s easy to find?"}, {"id": "f2", "type": "textarea", "label": "What does your body feel like as you say the phrase slowly?"}, {"id": "f3", "type": "textarea", "label": "Who is one person you could say this phrase out loud with?"}, {"id": "f4", "type": "textarea", "label": "What situation this week might call for this card?"}]'::jsonb, array['PTSD and trauma', 'grounding', 'wise mind', 'core DBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('low-mood-prediction-fact-check-card', 'Low-Mood Prediction Fact-Check Card', 'dbt'::resource_kind, 'Checks a depressive prediction against the actual facts of a specific situation.', 'Use it to slow down a low-mood prediction long enough to check it against facts.', array['Adults', 'Teens']::text[], '10 minutes', 'Have the client name a specific prediction low mood is making about an upcoming situation, like ''it will be pointless,'' then walk through the actual facts available right now rather than the felt certainty. This is a direct application of checking the facts, aimed specifically at the flat, foregone-conclusion quality low mood gives predictions. Clients often say the facts don''t matter because the feeling is so strong; note that down as data rather than arguing with it, and revisit the card after the situation actually happens.', '[{"id": "f0", "type": "textarea", "label": "What is low mood predicting about this situation?"}, {"id": "f1", "type": "textarea", "label": "What are the actual facts you know right now?"}, {"id": "f2", "type": "textarea", "label": "How certain does the prediction feel, 0 to 100?"}, {"id": "f3", "type": "textarea", "label": "What happened afterward, compared to the prediction?"}, {"id": "f4", "type": "textarea", "label": "What will you check the facts on next?"}]'::jsonb, array['depression', 'check the facts', 'core DBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-task-avoidance-card', 'Opposite Action for Task Avoidance Card', 'dbt'::resource_kind, 'Applies opposite action to the urge to avoid a boring or overwhelming task.', 'Use it to practice starting a task despite the urge to put it off.', array['Adults', 'Teens']::text[], '10 minutes', 'When the client notices the urge to avoid a task, have them name the urge and its opposite action, such as opening the document instead of closing the tab, then commit to two minutes of the opposite action only. This is opposite action applied specifically to task avoidance rather than to an emotion, so keep the ask small and time-boxed. Clients often wait for motivation before starting; note that the opposite action is meant to come before any change in how they feel, not after it.', '[{"id": "f0", "type": "textarea", "label": "What task are you avoiding right now?"}, {"id": "f1", "type": "textarea", "label": "What is the urge telling you to do instead?"}, {"id": "f2", "type": "textarea", "label": "What is the opposite action, in one small step?"}, {"id": "f3", "type": "textarea", "label": "Did you do two minutes of the opposite action? What happened?"}, {"id": "f4", "type": "textarea", "label": "What made starting easier or harder than expected?"}]'::jsonb, array['ADHD', 'opposite action', 'core DBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('life-worth-living-recovery-card', 'Life Worth Living Recovery Card', 'dbt'::resource_kind, 'Names concrete pieces of a life worth living to weigh against substance use urges.', 'Use it to keep a concrete, positive reason for change in view during hard moments.', array['Adults']::text[], '15 minutes', 'Ask the client to name a few specific, believable pieces of a life they want to build, not abstractions, and write them on a card small enough to carry. When an urge shows up, the card is a quick way to check the moment against the bigger picture rather than arguing with the urge directly. Clients sometimes reach for a vague or idealized version of their life; keep pushing for specifics they actually recognize as theirs. Update the card together every few sessions as what matters to them shifts.', '[{"id": "f0", "type": "textarea", "label": "Name three specific things that would be part of a life worth living for you."}, {"id": "f1", "type": "textarea", "label": "Which one feels most within reach right now?"}, {"id": "f2", "type": "textarea", "label": "When an urge shows up, what would using take away from this list?"}, {"id": "f3", "type": "textarea", "label": "What is one action this week that moves toward this list?"}, {"id": "f4", "type": "textarea", "label": "What would you add or change on this card today?"}]'::jsonb, array['addiction', 'urges', 'core DBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('radically-accepting-uncertainty-log', 'Radically Accepting Uncertainty Log', 'dbt'::resource_kind, 'Applies radical acceptance to the not-knowing that intrusive thoughts demand answers for.', 'Use it to practice accepting uncertainty rather than fighting for proof.', array['Adults', 'Teens']::text[], '15 minutes', 'Run the client through the radical acceptance steps applied specifically to a moment of not-knowing rather than to suffering in general; clarify carefully that accepting the uncertainty is not the same as accepting that the feared outcome is true, since that fusion is where this exercise most often goes sideways for someone with intrusive thoughts.', '[{"id": "f0", "type": "textarea", "label": "What am I being asked to accept not knowing for certain?"}, {"id": "f1", "type": "textarea", "label": "What does my body do when I stop trying to resolve it?"}, {"id": "f2", "type": "textarea", "label": "What would radically accepting this moment look like?"}, {"id": "f3", "type": "textarea", "label": "What is one small way I can practice that today?"}]'::jsonb, array['OCD', 'radical acceptance', 'uncertainty']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('cold-water-reset-card', 'Cold Water Reset Card', 'dbt'::resource_kind, 'Uses a fast temperature change to bring a racing panic response down quickly.', 'Use it to teach the temperature half of TIPP as a quick physical reset.', array['Adults', 'Teens']::text[], 'Five minutes', 'Practice this in session first, holding cold water on the face or wrists or gripping ice, and check for any heart condition before recommending it as homework; hand over the card once the client has felt the reset happen once with you, and watch for it becoming a way to avoid ever letting a milder wave of panic simply pass on its own.', '[{"id": "f0", "type": "textarea", "label": "Where can I keep something cold within reach, like the fridge or a bathroom sink?"}, {"id": "f1", "type": "textarea", "label": "How did my body feel right before I used it?"}, {"id": "f2", "type": "textarea", "label": "How did it feel about thirty seconds after?"}, {"id": "f3", "type": "textarea", "label": "When would I reach for this versus just riding the wave out?"}]'::jsonb, array['panic attacks', 'TIPP', 'distress tolerance']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-postpartum-withdrawal', 'Opposite Action for Postpartum Withdrawal', 'dbt'::resource_kind, 'Uses opposite action to counter the pull to hide from support when things feel hard.', 'Use it to practice reaching out even when shame urges someone to withdraw.', array['Adults']::text[], '15 minutes', 'Walk through the standard opposite action steps applied to withdrawing from a partner or friends: name the emotion driving the pull, often shame or overwhelm, check whether hiding actually fits the facts of the situation, then plan a small opposite action such as one short text or accepting a single offer of help; watch for the action being done so partially it never actually creates contact.', '[{"id": "f0", "type": "textarea", "label": "What emotion is pulling me to withdraw right now?"}, {"id": "f1", "type": "textarea", "label": "Does hiding actually fit the facts of the situation?"}, {"id": "f2", "type": "textarea", "label": "What would the opposite action look like, specifically?"}, {"id": "f3", "type": "textarea", "label": "Who is one person I could reach out to today?"}]'::jsonb, array['perinatal and postpartum', 'opposite action', 'emotion regulation']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-self-doubt', 'Opposite Action for Self-Doubt', 'dbt'::resource_kind, 'Uses opposite action to counter the urge to shrink back when self-worth feels shaky.', 'Use it to practice showing up despite the pull to hide or downplay oneself.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk through opposite action steps applied to the urge to stay quiet, avoid eye contact, or minimize oneself when self-doubt spikes; check whether the urge fits the facts of the moment, then plan one small opposite action such as speaking up once in a meeting or accepting a compliment out loud, and watch for a client choosing an action so small it doesn''t register as a real stretch.', '[{"id": "f0", "type": "textarea", "label": "What is the urge to shrink back telling me to do right now?"}, {"id": "f1", "type": "textarea", "label": "Does that urge actually fit the facts of the situation?"}, {"id": "f2", "type": "textarea", "label": "What would the opposite action look like, specifically?"}, {"id": "f3", "type": "textarea", "label": "What happened in my body when I tried it?"}]'::jsonb, array['self-esteem', 'opposite action', 'core DBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('give-skills-for-small-talk', 'GIVE Skills for Small Talk', 'dbt'::resource_kind, 'Applies the GIVE skill to the specific discomfort of making small talk.', 'Use it to give someone a concrete script for GIVE in low-stakes conversation.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk through each letter of gentle, interested, validate, and easy manner with a small-talk example, then have the client script one actual line for each before their next low-stakes conversation; watch for over-scripting to the point that the exchange feels rehearsed rather than easier, since the goal is a starting point, not a transcript to memorize.', '[{"id": "f0", "type": "textarea", "label": "Gentle: one thing I could say without an edge to it."}, {"id": "f1", "type": "textarea", "label": "Interested: one question I could ask the other person."}, {"id": "f2", "type": "textarea", "label": "Validate: one thing I could say back that shows I heard them."}, {"id": "f3", "type": "textarea", "label": "Easy manner: one small bit of humor or lightness I could add."}, {"id": "f4", "type": "textarea", "label": "Which of these feels hardest to actually do?"}]'::jsonb, array['social anxiety', 'GIVE', 'interpersonal effectiveness']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-of-partner-differences-practice', 'Radical Acceptance of Partner Differences Practice', 'dbt'::resource_kind, 'Applies radical acceptance to a partner trait a client keeps fighting.', 'Use it to help a client stop the extra suffering of refusing to accept a fixed difference.', array['Adults']::text[], '20 minutes', 'Use this for a client stuck resenting a partner trait unlikely to change — a difference in tidiness, sociability, or emotional expression — rather than an active safety concern. Walk through radical acceptance: naming the difference as real, noticing the added suffering the resistance itself creates, and practicing a phrase that accepts the fact without approving of it. Clients sometimes confuse acceptance with agreeing the difference is fine; clarify it means dropping the fight against reality while still deciding what boundaries or requests make sense.', '[{"id": "f0", "type": "textarea", "label": "The difference between us I keep fighting against…"}, {"id": "f1", "type": "textarea", "label": "How I usually react when this difference shows up…"}, {"id": "f2", "type": "textarea", "label": "What refusing to accept this costs me…"}, {"id": "f3", "type": "textarea", "label": "A radical acceptance phrase I can say to myself…"}, {"id": "f4", "type": "textarea", "label": "What I can still ask for or set a boundary about, separate from acceptance…"}]'::jsonb, array['relationship issues', 'radical acceptance', 'core DBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('tipp-for-body-alarm-spikes-card', 'TIPP for Body Alarm Spikes Card', 'dbt'::resource_kind, 'Walks a client through TIPP skills when body alarm spikes in session.', 'Use it to bring a client''s intense physical distress down fast and safely in session.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Keep this card ready for a moment in session when a client''s distress spikes hard and fast — racing heart, shaking, feeling unable to stay in the room. Walk them through one TIPP option live: cold water on the face or hands, paced exhale-longer breathing, or brief intense movement, whatever fits your space. This is a here-and-now tool done together in session, not homework for a crisis alone; if distress is severe or the client mentions wanting to end their life, name 988 (call or text) as an option right then. Watch for a client who uses it to suppress the spike rather than ride it out.', '[{"id": "f0", "type": "textarea", "label": "What I''m noticing in my body right now, from head to toe…"}, {"id": "f1", "type": "textarea", "label": "The TIPP option I''m trying right now: cold, paced breathing, or movement…"}, {"id": "f2", "type": "textarea", "label": "My distress level before, 0 to 10…"}, {"id": "f3", "type": "textarea", "label": "My distress level after a few minutes…"}, {"id": "f4", "type": "textarea", "label": "If this gets worse when I''m not with my therapist, 988 (call or text) is here…"}]'::jsonb, array['sexual abuse', 'distress tolerance', 'TIPP']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('opposite-action-approach-card', 'Opposite Action Approach Card', 'dbt'::resource_kind, 'Uses opposite action to move toward a feared object instead of away from it.', 'Use it to help a client act against the urge to avoid when fear doesn''t fit the actual risk.', array['Adults', 'Teens']::text[], '15 minutes', 'Use this with a client who agrees the fear they feel around a specific object or situation is out of proportion to the actual risk. Walk through the opposite action steps: name the fear, check whether it fits the facts, and if it doesn''t, commit to acting opposite to the avoidance urge all the way — approaching fully rather than halfway. Half-hearted opposite action tends to backfire, so coach the client toward a step they can complete fully rather than a bigger one they''ll bail out of partway through.', '[{"id": "f0", "type": "textarea", "label": "The fear and the situation it shows up in…"}, {"id": "f1", "type": "textarea", "label": "Does the fear fit the actual risk here? Why or why not…"}, {"id": "f2", "type": "textarea", "label": "The avoidance urge I''m noticing…"}, {"id": "f3", "type": "textarea", "label": "The opposite action I''ll take, all the way through…"}, {"id": "f4", "type": "textarea", "label": "How it went, and what I noticed in my body afterward…"}]'::jsonb, array['phobias', 'opposite action', 'core DBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-appearance-avoidance-card', 'Opposite Action for Appearance Avoidance Card', 'dbt'::resource_kind, 'Uses opposite action to face situations a client avoids due to appearance shame.', 'Use it to help a client re-enter situations they skip because of how they think they look.', array['Adults', 'Teens']::text[], '15 minutes', 'Use this with a client who skips photos, gatherings, or activities specifically because of shame about their appearance. Check whether the shame fits the actual situation — is anyone actually going to judge them the way they fear — and if it doesn''t fit, walk through committing to the opposite action of showing up fully rather than partially. A client might attend but hide at the edges, which blunts the exercise; coach toward full participation for it to work. Note what the client notices afterward about how much attention others actually paid to their appearance.', '[{"id": "f0", "type": "textarea", "label": "The situation I usually avoid because of how I think I look…"}, {"id": "f1", "type": "textarea", "label": "The shame I feel about it…"}, {"id": "f2", "type": "textarea", "label": "Does that shame fit what''s actually likely to happen? Why or why not…"}, {"id": "f3", "type": "textarea", "label": "The opposite action I''ll commit to, fully…"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward, especially about others'' attention…"}]'::jsonb, array['body image', 'opposite action', 'core DBT']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('shared-vision-conversation-cards', 'Shared Vision Conversation Cards', 'couples'::resource_kind, 'A set of conversation prompts where partners describe the life they picture together.', 'Use it to help partners compare their long-term pictures before setting shared goals.', array['Couples']::text[], 'Full session', 'Partner A and Partner B each answer the same set of prompts about where they picture themselves in five or ten years, separately at first, then read their answers to each other. Couples often assume they already know each other''s picture and are surprised by a gap in timing or priority; treat any mismatch as information to plan around, not a problem to resolve on the spot. Use the overlaps to draft one or two shared goals to revisit later.', '[{"id": "f0", "type": "textarea", "label": "Partner A: describe a normal day in your life five years from now."}, {"id": "f1", "type": "textarea", "label": "Partner B: describe a normal day in your life five years from now."}, {"id": "f2", "type": "textarea", "label": "Where do your two pictures overlap?"}, {"id": "f3", "type": "textarea", "label": "Where do they pull in different directions?"}, {"id": "f4", "type": "textarea", "label": "What''s one shared goal you could set based on the overlap?"}]'::jsonb, array['goal setting', 'values', 'connection']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('personal-space-needs-negotiation', 'Personal Space Needs Negotiation', 'couples'::resource_kind, 'A worksheet where each partner names how much separate time and space they need.', 'Use it to turn a vague tension over togetherness into a concrete, workable agreement.', array['Couples']::text[], '20 minutes', 'Partner A and Partner B each estimate how much time alone or with separate friends they need in a typical week, then compare numbers and negotiate a plan both can live with. The conversation often stalls when one partner hears the other''s need for space as rejection; name that reading out loud and separate the need from what it means about the relationship. Write the agreed plan down and revisit it if either partner''s needs shift.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how much time alone do you need most weeks?"}, {"id": "f1", "type": "textarea", "label": "Partner B: how much time alone do you need most weeks?"}, {"id": "f2", "type": "textarea", "label": "What does it feel like when your partner asks for space?"}, {"id": "f3", "type": "textarea", "label": "Where do your numbers create tension?"}, {"id": "f4", "type": "textarea", "label": "What plan can you both agree to try this month?"}]'::jsonb, array['boundaries', 'needs', 'communication']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('shared-decision-values-grid', 'Shared Decision Values Grid', 'couples'::resource_kind, 'A grid where partners score a shared decision against each of their own values.', 'Use it to help a couple see where their values agree and where they diverge on a choice.', array['Couples']::text[], '20 minutes', 'Partner A and Partner B each list what matters to them about a decision they''re facing together, then score the options on the table against both lists side by side. Couples often discover they''ve been arguing about the decision itself when the real gap is in which value should win when two matter at once; slow down and name that trade-off directly. Use the grid to negotiate which value takes priority this time, and note it for next time.', '[{"id": "f0", "type": "textarea", "label": "What decision are you facing together?"}, {"id": "f1", "type": "textarea", "label": "Partner A: what matters most to you about it?"}, {"id": "f2", "type": "textarea", "label": "Partner B: what matters most to you about it?"}, {"id": "f3", "type": "textarea", "label": "Where do your value lists agree?"}, {"id": "f4", "type": "textarea", "label": "Where do they pull in different directions, and how will you decide?"}]'::jsonb, array['decisions', 'values', 'communication']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('talking-stick-turn-taking-exercise', 'Talking Stick Turn-Taking Exercise', 'couples'::resource_kind, 'A structured exercise where only the partner holding an object may speak.', 'Use it to slow down a conversation so each partner is fully heard before replying.', array['Couples']::text[], '20 minutes', 'Give the couple any small object to pass back and forth: only the partner holding it may speak, and the other must reflect back what they heard before asking for the object themselves. Partners usually break the rule within the first minute by jumping in to correct or defend; gently reset the object rather than letting the conversation slide back into normal cross-talk. Run it on a low-stakes topic first before using it for a harder conversation.', '[{"id": "f0", "type": "textarea", "label": "Partner A: while holding the object, share your view without interruption."}, {"id": "f1", "type": "textarea", "label": "Partner B: reflect back what you heard before responding."}, {"id": "f2", "type": "textarea", "label": "Partner B: now share your view, holding the object."}, {"id": "f3", "type": "textarea", "label": "Partner A: reflect back what you heard."}, {"id": "f4", "type": "textarea", "label": "What was different about being heard this way?"}]'::jsonb, array['communication', 'listening', 'connection']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('shared-daily-routine-redesign', 'Shared Daily Routine Redesign', 'couples'::resource_kind, 'A worksheet where partners map their daily routines and redesign the friction points.', 'Use it to help a couple rebuild shared routines that have quietly stopped working.', array['Couples']::text[], 'One week', 'Partner A and Partner B each sketch out a typical weekday hour by hour, then compare charts to find moments where their routines collide, conflict, or leave one partner carrying more than the other. Couples often find the friction point is a small logistics issue rather than a bigger relationship problem; resist the urge to over-interpret a scheduling clash. Pick one friction point to redesign together and try the new routine for a week before reviewing.', '[{"id": "f0", "type": "textarea", "label": "Partner A: sketch your typical weekday, hour by hour."}, {"id": "f1", "type": "textarea", "label": "Partner B: sketch your typical weekday, hour by hour."}, {"id": "f2", "type": "textarea", "label": "Where do your two routines collide or create friction?"}, {"id": "f3", "type": "textarea", "label": "Which one friction point will you redesign first?"}, {"id": "f4", "type": "textarea", "label": "What will you try instead this week?"}]'::jsonb, array['habits', 'routines', 'communication']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('nightmare-aftermath-support-plan', 'Nightmare Aftermath Support Plan', 'couples'::resource_kind, 'Plans how each partner responds when one wakes from a trauma-related nightmare.', 'Use it to turn a startled overnight moment into a rehearsed, calmer routine for both partners.', array['Couples']::text[], '30 minutes', 'Have each partner describe, separately then together, what actually helps them return to feeling safe after a nightmare and what unintentionally makes it worse, such as being touched suddenly or being asked what the dream was about. Couples often default to the waking partner''s own instincts rather than what their partner has said helps; slow this down and write both preferences on the same page. The tool never asks either partner to recount the dream content itself, only what helps them settle afterward, and works best rehearsed calmly rather than introduced for the first time overnight.', '[{"id": "f0", "type": "textarea", "label": "Partner having the nightmare: what usually helps you feel safe again?"}, {"id": "f1", "type": "textarea", "label": "Partner having the nightmare: what should your partner NOT do in that moment?"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what do you tend to do right now when this happens?"}, {"id": "f3", "type": "textarea", "label": "Both: what will your partner say or do first, before anything else?"}, {"id": "f4", "type": "textarea", "label": "Both: how will you check in with each other the next morning?"}]'::jsonb, array['PTSD and trauma', 'couples', 'sleep', 'support']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('worry-spillover-conversation-for-partners', 'Worry Spillover Conversation for Partners', 'couples'::resource_kind, 'Helps both partners name how one partner''s worry affects the other and set limits.', 'Use it to separate supporting a worried partner from absorbing their worry.', array['Couples']::text[], '30 minutes', 'Have the worried partner describe what kind of support actually helps versus what just moves the worry onto their partner, such as needing repeated reassurance late in the evening. Have the other partner name where they feel the spillover in their own mood or sleep, without blame. Couples often skip straight to ''stop worrying'' as the ask; redirect toward a specific, workable limit both partners can agree to, like a set reassurance window each evening. Revisit the agreement after a week rather than expecting it to hold perfectly the first time.', '[{"id": "f0", "type": "textarea", "label": "Worried partner: what kind of support actually helps you in the moment?"}, {"id": "f1", "type": "textarea", "label": "Worried partner: what does your partner do that doesn''t help, even if well meant?"}, {"id": "f2", "type": "textarea", "label": "Other partner: where do you notice the worry landing on you?"}, {"id": "f3", "type": "textarea", "label": "Both: what is one specific limit you can agree to try this week?"}, {"id": "f4", "type": "textarea", "label": "Both: when will you check back in on how the limit is working?"}]'::jsonb, array['anxiety', 'couples', 'support', 'communication']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('interruption-pattern-repair-conversation', 'Interruption Pattern Repair Conversation', 'couples'::resource_kind, 'Helps both partners name and repair a pattern of interrupting during talks.', 'Use it to turn a recurring interruption pattern into a repairable, non-blaming routine.', array['Couples']::text[], '30 minutes', 'Have the interrupting partner describe what pulls their attention mid-conversation and how it feels from the inside, while the other partner describes what it feels like to be cut off, without either side turning it into a character judgment. Couples often land on ''you don''t care'' or ''you can''t help it'' as the whole story; push past both to a workable repair signal, like a hand gesture that means ''let me finish,'' that either partner can use in the moment. Practice the signal once in session before sending it home as homework.', '[{"id": "f0", "type": "textarea", "label": "Interrupting partner: what usually pulls your attention away mid-sentence?"}, {"id": "f1", "type": "textarea", "label": "Other partner: what does it feel like when this happens?"}, {"id": "f2", "type": "textarea", "label": "What signal will you use to mean ''let me finish''?"}, {"id": "f3", "type": "textarea", "label": "What will the interrupting partner do when they see that signal?"}, {"id": "f4", "type": "textarea", "label": "How will you check in with each other after trying this for a week?"}]'::jsonb, array['ADHD', 'couples', 'communication']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('recovery-trust-milestones-conversation', 'Recovery Trust Milestones Conversation', 'couples'::resource_kind, 'Names concrete trust milestones both partners can track as recovery continues.', 'Use it to give both partners a shared, specific way to track rebuilding trust.', array['Couples']::text[], '30 minutes', 'Have both partners name specific, observable milestones that would signal trust is rebuilding, such as an agreed check-in call or an unprompted update, rather than a vague sense of ''feeling better about it.'' The partner in recovery names what support would actually help hit each milestone, and the other partner names what checking in without becoming a monitor could look like. Couples often set either impossibly high or vague milestones; keep pushing both toward something specific and time-bound, and revisit the list together every few weeks.', '[{"id": "f0", "type": "textarea", "label": "Partner in recovery: what is one specific milestone that would show progress?"}, {"id": "f1", "type": "textarea", "label": "Partner in recovery: what support would help you reach it?"}, {"id": "f2", "type": "textarea", "label": "Other partner: what would checking in, without monitoring, look like for you?"}, {"id": "f3", "type": "textarea", "label": "Both: what milestone will you track over the next two weeks?"}, {"id": "f4", "type": "textarea", "label": "Both: how will you know, together, that it''s been met?"}]'::jsonb, array['addiction', 'couples', 'trust']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('ritual-participation-boundary-script', 'Ritual Participation Boundary Script', 'couples'::resource_kind, 'Helps both partners agree on which rituals the partner will stop taking part in.', 'Use it to script a caring way to step back from performing rituals together.', array['Couples']::text[], '30 minutes', 'Have each partner name the specific tasks the supporting partner currently does or repeats, such as double-checking locks or answering the same question, agree on one to phase out first, and script a short caring line to say instead of doing it; expect pushback or guilt in the first attempts and plan for it rather than treating a single setback as failure.', '[{"id": "f0", "type": "textarea", "label": "Partner A: which rituals do I currently take part in or complete for you?"}, {"id": "f1", "type": "textarea", "label": "Partner B: which of these would you like help stepping back from first?"}, {"id": "f2", "type": "textarea", "label": "What can Partner A say instead of doing the ritual?"}, {"id": "f3", "type": "textarea", "label": "How will we handle it if things feel harder at first?"}, {"id": "f4", "type": "textarea", "label": "How will we notice and mark progress together?"}]'::jsonb, array['OCD', 'accommodation', 'boundaries']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('supporter-burnout-check-in', 'Supporter Burnout Check-In', 'couples'::resource_kind, 'Gives the partner who does the reassuring a space to name their own strain.', 'Use it to check the supporting partner isn''t quietly wearing thin.', array['Couples']::text[], '20 minutes', 'Unlike tools about what to do during or after an episode, this one centers what repeated support has cost the supporting partner; have them name the hardest part and what they need for themselves, and have the partner with panic simply listen without jumping to reassure them back or apologize the conversation away.', '[{"id": "f0", "type": "textarea", "label": "Partner supporting: what has been hardest about being the calm one during these episodes?"}, {"id": "f1", "type": "textarea", "label": "Partner supporting: what do you need more of for yourself?"}, {"id": "f2", "type": "textarea", "label": "Partner with panic: what did you not know about the cost to your partner?"}, {"id": "f3", "type": "textarea", "label": "What is one thing we can change so support is sustainable?"}]'::jsonb, array['panic attacks', 'support', 'relationship issues']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('parenting-style-differences-map', 'Parenting Style Differences Map', 'couples'::resource_kind, 'Names both partners'' upbringing-shaped instincts before they clash over a child.', 'Use it to trace parenting reactions back to each partner''s own upbringing.', array['Couples']::text[], '30 minutes', 'Have each partner recall how their own parents typically handled one recurring flashpoint, such as bedtime or tantrums, then compare where their instincts agree and where they pull apart, ending with one shared approach to try for that specific moment; keep the conversation on today''s approach rather than letting it turn into re-litigating either partner''s childhood.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how did your own parents typically handle this kind of moment?"}, {"id": "f1", "type": "textarea", "label": "Partner B: how did your own parents typically handle this kind of moment?"}, {"id": "f2", "type": "textarea", "label": "Where do our instincts agree?"}, {"id": "f3", "type": "textarea", "label": "Where do they pull in different directions?"}, {"id": "f4", "type": "textarea", "label": "What is one shared approach we can try this week?"}]'::jsonb, array['parenting', 'relationship issues', 'communication']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('low-self-worth-support-signal', 'Low Self-Worth Support Signal', 'couples'::resource_kind, 'Gives both partners a private signal for when self-worth dips need support.', 'Use it to agree on how one partner can ask for support without over-explaining.', array['Couples']::text[], '20 minutes', 'Have the partner who struggles with self-worth name the situations that tend to trigger a dip and agree on a low-effort signal, a word or gesture, that tells their partner support is wanted; the supporting partner names what they usually do that lands as fixing or over-reassuring instead of helping, and both agree on one thing to try next time the signal appears.', '[{"id": "f0", "type": "textarea", "label": "Partner with the dip: what situations tend to trigger it?"}, {"id": "f1", "type": "textarea", "label": "Partner with the dip: what signal could tell your partner you need support?"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what do you usually do that doesn''t quite land?"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: what will you try instead when you see the signal?"}]'::jsonb, array['self-esteem', 'support', 'communication']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('social-event-wingman-plan', 'Social Event Wingman Plan', 'couples'::resource_kind, 'Names how a partner can help without hovering at a social event.', 'Use it to agree on specific support at events, not blanket rescuing.', array['Couples']::text[], '20 minutes', 'Have the anxious partner name what actually helps at an event, such as an exit signal, a check-in every twenty minutes, or being introduced rather than left to start conversations alone, versus what feels like being babysat; the supporting partner names what they need in return, like permission to also enjoy the event, and watch for a plan that leaves the anxious partner never having to initiate anything.', '[{"id": "f0", "type": "textarea", "label": "Partner with anxiety: what kind of support actually helps at an event?"}, {"id": "f1", "type": "textarea", "label": "Partner with anxiety: what feels like being babysat instead of supported?"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what do you need so this doesn''t fall only on you?"}, {"id": "f3", "type": "textarea", "label": "What is our signal if it''s time to leave or take a break?"}]'::jsonb, array['social anxiety', 'support', 'communication']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('speaker-listener-turn-card', 'Speaker-Listener Turn Card', 'couples'::resource_kind, 'Structures a hard conversation into speaker and listener turns with a hand-off object.', 'Use it to slow a couple''s conversation enough for each partner to actually be heard.', array['Couples']::text[], '20 minutes', 'Give the couple a small object to pass between them — only the partner holding it may speak, in short statements, while the other partner listens and then paraphrases before responding. Switch the object after each paraphrase is accepted as accurate. Couples used to interrupting each other find the pacing awkward at first and may want to abandon it mid-conversation; encourage them to finish one full round before deciding it isn''t working. Watch for a listening partner who paraphrases the words but not the feeling underneath them.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I want to say, in one or two short sentences…"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I heard Partner A say…"}, {"id": "f2", "type": "textarea", "label": "Partner A: did that paraphrase land? What''s still missing…"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I want to say now that it''s my turn…"}, {"id": "f4", "type": "textarea", "label": "Partner A: what I heard Partner B say…"}, {"id": "f5", "type": "textarea", "label": "Both: what felt different about talking this way…"}]'::jsonb, array['relationship issues', 'communication', 'relationships']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('pause-signal-agreement-for-partners', 'Pause Signal Agreement for Partners', 'couples'::resource_kind, 'Sets a shared signal both partners use to pause touch in the moment.', 'Use it to give both partners a clear, low-pressure way to pause physical closeness.', array['Couples']::text[], '20 minutes', 'Have both partners agree on a simple word or gesture either one can use, at any point, to pause physical touch without needing to explain why in the moment. Practice it once in session on something low-stakes, like a hand-hold, so both partners feel what a respected pause looks like. The partner receiving the signal responds only with acknowledgment, saving questions or hurt feelings for a later conversation. This stays on present-moment pacing and consent, never on reviewing past events; if either partner starts describing a past incident in detail, redirect to the agreement itself.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the word or gesture I''ll use to signal pause…"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I''ll respond when I see or hear that signal…"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I need after a pause before we continue…"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need to hear to feel okay about a pause…"}, {"id": "f4", "type": "textarea", "label": "Both: when we''ll check in about how the signal is working…"}]'::jsonb, array['sexual abuse', 'pacing', 'consent']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('partner-coping-support-handoff-plan', 'Partner Coping Support Handoff Plan', 'couples'::resource_kind, 'Plans what each partner does when the other reaches for a coping skill mid-stress.', 'Use it to help partners support each other''s coping without taking it over.', array['Couples']::text[], '20 minutes', 'Have each partner separately name their own two or three go-to coping skills, then swap sheets and talk through what the other partner can do to make room for that skill — stepping back, staying nearby without talking, or offering a specific phrase. This heads off a common pattern where a supportive partner accidentally interrupts coping by hovering or asking too many questions in the moment. Have both partners agree on one small cue the coping partner can give — a word or gesture — that means ''give me a few minutes,'' and check back in a few weeks on whether the handoff is working.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my go-to coping skills are…"}, {"id": "f1", "type": "textarea", "label": "Partner A: what helps me use them, and what gets in the way…"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I''ll do to make room for Partner A''s coping skill…"}, {"id": "f3", "type": "textarea", "label": "Partner B: my go-to coping skills are…"}, {"id": "f4", "type": "textarea", "label": "Partner A: what I''ll do to make room for Partner B''s coping skill…"}, {"id": "f5", "type": "textarea", "label": "Both: our cue for ''give me a few minutes'' is…"}]'::jsonb, array['coping skills', 'relationships', 'communication']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('appearance-comment-ground-rules-for-partners', 'Appearance Comment Ground Rules for Partners', 'couples'::resource_kind, 'Sets shared rules for how partners talk about each other''s appearance.', 'Use it to help partners agree on what appearance comments help versus hurt.', array['Couples']::text[], '20 minutes', 'Have each partner separately list appearance-related comments that help them and ones that land badly, even when well-intended, then compare lists together. A common surprise is a comment meant as reassurance landing as pressure to look a certain way; naming this out loud heads off repeated missteps. Agree on one or two ground rules going forward, such as complimenting something other than appearance or asking before commenting at all. Revisit the rules if either partner''s preferences shift.', '[{"id": "f0", "type": "textarea", "label": "Partner A: an appearance comment that actually helps me…"}, {"id": "f1", "type": "textarea", "label": "Partner A: an appearance comment that lands badly, even if well-meant…"}, {"id": "f2", "type": "textarea", "label": "Partner B: an appearance comment that actually helps me…"}, {"id": "f3", "type": "textarea", "label": "Partner B: an appearance comment that lands badly, even if well-meant…"}, {"id": "f4", "type": "textarea", "label": "Both: one ground rule we''re agreeing to going forward…"}]'::jsonb, array['body image', 'relationships', 'communication']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('gratitude-garden-growth-chart', 'Gratitude Garden Growth Chart', 'kids'::resource_kind, 'A craft where a child adds a paper flower to a growing garden for each thing they''re glad about.', 'Use it to build a daily gratitude habit a child can see growing on the wall.', array['Children']::text[], 'Five minutes daily for several weeks', 'The child decorates a paper flower and writes or draws one thing they''re glad about, adding it to a garden poster on the wall each day; the parent sets aside the same few minutes daily and asks the child to point to their favorite flower so far. Some children run out of new ideas after a few days; the parent can prompt with a specific moment from that day rather than asking a general question. Watch for the child starting to notice good moments unprompted as the garden fills in.', '[{"id": "f0", "type": "textarea", "label": "Draw or write one thing you''re glad about today."}, {"id": "f1", "type": "textarea", "label": "Decorate your flower however you like."}, {"id": "f2", "type": "textarea", "label": "Add it to your garden. How many flowers do you have now?"}, {"id": "f3", "type": "textarea", "label": "Which flower is your favorite so far, and why?"}, {"id": "f4", "type": "textarea", "label": "Tell a grown-up about one flower today."}]'::jsonb, array['gratitude', 'children', 'art']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('solve-it-superhero-comic-strip', 'Solve-It Superhero Comic Strip', 'kids'::resource_kind, 'A comic strip a child draws showing a superhero solving a small everyday problem step by step.', 'Use it to teach a child a simple problem-solving sequence through a story they draw.', array['Children']::text[], '30 minutes', 'The child draws a four-box comic strip where a superhero of their own design notices a problem, thinks of a few ideas, picks one, and tries it out, with the parent asking what happens next at each box. Children often jump straight to the solution box and skip generating more than one idea; the parent can pause and ask what else could the hero try before moving on. Keep finished strips to reference the next time the child faces a real problem of their own.', '[{"id": "f0", "type": "textarea", "label": "Box 1: draw your superhero noticing a problem."}, {"id": "f1", "type": "textarea", "label": "Box 2: draw or list two or three ideas the hero has."}, {"id": "f2", "type": "textarea", "label": "Box 3: draw the hero picking one idea and trying it."}, {"id": "f3", "type": "textarea", "label": "Box 4: draw what happens next."}, {"id": "f4", "type": "textarea", "label": "What real problem of yours could your hero help with?"}]'::jsonb, array['problem solving', 'children', 'art']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('speak-up-puppet-script', 'Speak-Up Puppet Script', 'kids'::resource_kind, 'A puppet a child makes and uses to practice saying an assertive sentence out loud.', 'Use it to help a child rehearse standing up for themselves in a low-pressure way.', array['Children']::text[], '20 minutes', 'The child decorates a simple sock or paper-bag puppet, then uses it to practice saying a short assertive line, such as please stop or I want a turn too, while the parent plays the other character and reacts. Children often mumble the line or laugh it off at first; let the puppet carry the boldness so the child doesn''t have to, and repeat the line a few times before ending the session. Praise the specific words used, not just the effort.', '[{"id": "f0", "type": "textarea", "label": "Decorate your puppet. What''s its name?"}, {"id": "f1", "type": "textarea", "label": "What''s something you wish you could say to someone but haven''t?"}, {"id": "f2", "type": "textarea", "label": "Practice saying it through your puppet''s voice."}, {"id": "f3", "type": "textarea", "label": "How did it feel to say it out loud?"}, {"id": "f4", "type": "textarea", "label": "When could you try saying it for real?"}]'::jsonb, array['communication', 'assertiveness', 'children']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('my-big-goal-treasure-map', 'My Big Goal Treasure Map', 'kids'::resource_kind, 'A treasure map a child draws with stepping stones leading to a goal marked with an X.', 'Use it to break a child''s big goal into small, visible steps they can check off.', array['Children']::text[], '30 minutes', 'The child draws a map with their goal marked as buried treasure at one end, then adds stepping stones between the start and the X, each one a small step toward the goal; the parent helps name a realistic first stone and checks in on progress weekly. Children often draw a huge jump straight to the treasure with no stones in between; the parent can ask what would need to happen right before that to work backward into smaller steps.', '[{"id": "f0", "type": "textarea", "label": "What''s your treasure? Draw it and write what it is."}, {"id": "f1", "type": "textarea", "label": "Draw the first stepping stone: what''s the very first small step?"}, {"id": "f2", "type": "textarea", "label": "Add three more stepping stones between the start and the treasure."}, {"id": "f3", "type": "textarea", "label": "Which stone will you try to reach this week?"}, {"id": "f4", "type": "textarea", "label": "Color in a stone each time you reach it."}]'::jsonb, array['goal setting', 'children', 'art']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('decision-spinner-wheel-craft', 'Decision Spinner Wheel Craft', 'kids'::resource_kind, 'A paper spinner a child builds and uses to weigh choices in a made-up scenario.', 'Use it to give a child a hands-on way to practice thinking through choices and consequences.', array['Children']::text[], '30 minutes', 'The child builds a simple paper spinner divided into a few choices for a scenario the parent describes, spins to see which choice comes up, and then talks through what might happen next if they actually picked it. The parent''s job is to ask and then what a couple of times after each spin rather than telling the child the right answer. Children sometimes want to keep re-spinning until they land on their favorite choice; that''s a fine moment to talk about picking versus wishing.', '[{"id": "f0", "type": "textarea", "label": "Write three or four choices around your spinner."}, {"id": "f1", "type": "textarea", "label": "Spin it. Which choice did you land on?"}, {"id": "f2", "type": "textarea", "label": "What might happen next if you really picked that choice?"}, {"id": "f3", "type": "textarea", "label": "Would you actually pick that one, or a different one?"}, {"id": "f4", "type": "textarea", "label": "Why?"}]'::jsonb, array['decisions', 'children', 'art']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('safety-signal-bracelet-craft', 'Safety Signal Bracelet Craft', 'kids'::resource_kind, 'A child builds a wearable bracelet where each bead stands for one calming step.', 'Use it to give a child a wearable, always-available reminder of their calming steps.', array['Children']::text[], '20 minutes', 'Have the child string four or five beads, each one matched to a step they choose, such as a deep breath, naming a color in the room, or finding a grown-up. Parents help hold the string steady and can wear a matching bracelet themselves as a cue to check in together. Children sometimes want to add a bead for what scared them; keep the beads focused on calming steps only, not on retelling the event, and gently redirect if a story starts. Remind the parent of their duty to report any new disclosure of harm to the appropriate authority rather than handling it alone.', '[{"id": "f0", "type": "textarea", "label": "Pick a color for each calming step you want to remember."}, {"id": "f1", "type": "textarea", "label": "What will bead number one remind you to do?"}, {"id": "f2", "type": "textarea", "label": "Who will you show your bracelet to?"}, {"id": "f3", "type": "textarea", "label": "When might you need to look at your bracelet this week?"}, {"id": "f4", "type": "textarea", "label": "Grown-up: what will you do when you see your child touch the bracelet?"}]'::jsonb, array['PTSD and trauma', 'grounding', 'children', 'self-soothing']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('try-it-spinner-craft-for-worries', 'Try-It Spinner Craft for Worries', 'kids'::resource_kind, 'A child builds a spinner of small brave actions to try one at a time.', 'Use it to turn facing worries into a playful, low-stakes daily activity.', array['Children']::text[], '25 minutes', 'Help the child decorate a paper spinner with four or five small, doable actions that nudge against a specific worry, like saying hello first or trying a new food bite. The parent spins it with the child once a day and celebrates the attempt itself rather than how it turns out. Children sometimes want to skip the spin when it lands on something hard; let them spin again once, but not endlessly, so the exercise stays a stretch rather than an escape. Keep the actions small enough that most spins end in a genuine, sharable win.', '[{"id": "f0", "type": "textarea", "label": "Draw or write four small brave actions on your spinner."}, {"id": "f1", "type": "textarea", "label": "What did the spinner choose for you today?"}, {"id": "f2", "type": "textarea", "label": "How did it feel to try it, before and after?"}, {"id": "f3", "type": "textarea", "label": "Grown-up: what did you notice your child do well today?"}, {"id": "f4", "type": "textarea", "label": "What small brave action do you want to add next?"}]'::jsonb, array['anxiety', 'children', 'exposure']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('task-chunks-visual-chart-craft', 'Task Chunks Visual Chart Craft', 'kids'::resource_kind, 'A child builds a visual chart that breaks one chore into small stickered chunks.', 'Use it to make a multi-step task visible and completable one chunk at a time.', array['Children']::text[], '20 minutes', 'Help the child draw or paste four or five small pictures showing the steps of one chore, like cleaning a room, in the order they happen, leaving a spot for a sticker after each step. The parent sets a timer for just the next chunk rather than the whole chore and sits nearby while the child works. Children often want to jump ahead or skip steps; gently bring them back to the current chunk only. Celebrate the sticker, not the perfection of the finished chunk, and rebuild the chart together if a chore keeps stalling at the same step.', '[{"id": "f0", "type": "textarea", "label": "Draw the steps of your chore in order."}, {"id": "f1", "type": "textarea", "label": "Which chunk are you working on right now?"}, {"id": "f2", "type": "textarea", "label": "What sticker will you add when it''s done?"}, {"id": "f3", "type": "textarea", "label": "How did that chunk go?"}, {"id": "f4", "type": "textarea", "label": "Grown-up: which chunk does your child need the most help starting?"}]'::jsonb, array['ADHD', 'children', 'task initiation']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('my-support-people-chain-craft', 'My Support People Chain Craft', 'kids'::resource_kind, 'A child builds a paper chain of trusted adults to talk to on hard or confusing days.', 'Use it to give a child a visible, ready list of safe adults for hard days at home.', array['Children']::text[], '20 minutes', 'Have the child decorate paper links, one for each trusted adult they name, such as a parent, teacher, or relative, and link them into a chain to hang somewhere they see often. The parent''s job is to help the child pick real, available people and to add their own contact information to one link. Keep the focus on who the child can go to, not on describing what is happening at home, and never ask the child to explain a family member''s substance use as part of the activity. Follow your own reporting duties if the child discloses anything concerning while building it.', '[{"id": "f0", "type": "textarea", "label": "Who is one grown-up you trust? Add them to the chain."}, {"id": "f1", "type": "textarea", "label": "What could you say to them if you needed help?"}, {"id": "f2", "type": "textarea", "label": "Where will you hang your chain so you can see it?"}, {"id": "f3", "type": "textarea", "label": "Which link would you go to first on a hard day?"}, {"id": "f4", "type": "textarea", "label": "Grown-up: how will you check in with your child this week?"}]'::jsonb, array['addiction', 'children', 'support']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('where-anger-lives-body-map-craft', 'Where Anger Lives Body Map Craft', 'kids'::resource_kind, 'A child colors where anger shows up in their body and picks a calming spot for each.', 'Use it to connect a child''s body signals of anger to a specific calming action.', array['Children']::text[], '20 minutes', 'Give the child an outline of a body and have them color or mark where they notice anger, like a hot face or tight fists, then pick one calming action to pair with each spot, such as cool water on hot hands. The parent helps name spots the child might miss and keeps a copy of the finished map somewhere visible. Children sometimes color the whole body at once when upset; that''s useful information about how overwhelming the feeling is, not a wrong answer. Revisit the map together after a real anger episode to see if a new spot needs adding.', '[{"id": "f0", "type": "textarea", "label": "Color or mark where you feel anger in your body."}, {"id": "f1", "type": "textarea", "label": "What calming action goes with this spot?"}, {"id": "f2", "type": "textarea", "label": "Which spot shows up first when you start to get angry?"}, {"id": "f3", "type": "textarea", "label": "Grown-up: which spot did you notice on your child today?"}, {"id": "f4", "type": "textarea", "label": "What would you add to the map after today?"}]'::jsonb, array['anger management', 'children', 'emotion identification']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('brave-body-comic-strip', 'Brave Body Comic Strip', 'kids'::resource_kind, 'A child draws a comic of a scary body moment and the steps that helped.', 'Use it to turn a hard moment into a story the child can retell calmly.', array['Children']::text[], '20 minutes', 'Have the child draw a three or four panel comic covering what their body started doing, what they thought was happening, what helped, and how it ended; the parent''s job is to sit alongside and ask about each panel without correcting the child''s version, and if the child wants to skip the scary panel, let them draw it small instead of leaving it out.', '[{"id": "f0", "type": "textarea", "label": "Panel one: what did my body start doing?"}, {"id": "f1", "type": "textarea", "label": "Panel two: what did I think was happening?"}, {"id": "f2", "type": "textarea", "label": "Panel three: what did I do, or what did a grown-up do to help?"}, {"id": "f3", "type": "textarea", "label": "Panel four: how did it end?"}, {"id": "f4", "type": "textarea", "label": "What would I tell my body next time?"}]'::jsonb, array['panic attacks', 'children', 'art']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('sorry-and-solution-cards-craft', 'Sorry and Solution Cards Craft', 'kids'::resource_kind, 'A child decorates cards used to repair after a conflict at home.', 'Use it to give a child a concrete script for repairing after a blowup.', array['Children']::text[], '20 minutes', 'Have the child decorate a small set of cards, each holding a simple repair phrase or gesture like a hug or starting over, and keep them in a shared spot in the house; the parent''s role is to model picking a card after their own misstep too, not only hand them to the child, and watch for the ritual being used to end a conversation before feelings are actually heard.', '[{"id": "f0", "type": "textarea", "label": "What could I say when I want to make things better after a fight?"}, {"id": "f1", "type": "textarea", "label": "Draw or write one thing that helps me calm down first."}, {"id": "f2", "type": "textarea", "label": "Who in my family will I practice this with?"}, {"id": "f3", "type": "textarea", "label": "What does it feel like after we use a card?"}]'::jsonb, array['parenting', 'children', 'repair']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('growing-skills-tree-craft', 'Growing Skills Tree Craft', 'kids'::resource_kind, 'A child builds a tree that fills in with leaves for things they''ve gotten better at.', 'Use it to give a child visible evidence of growth, not only fixed praise.', array['Children']::text[], '20 minutes', 'Have the child draw or build a bare tree, then add a leaf whenever they notice something they can now do better than before, like tying shoes or being brave at a checkup; the parent''s role is to prompt for the before version each time so the growth is visible, not just praise the current skill, and watch for a child wanting to add leaves for things not yet actually practiced.', '[{"id": "f0", "type": "textarea", "label": "Draw your tree with no leaves yet."}, {"id": "f1", "type": "textarea", "label": "What is one thing you can do now that used to be hard?"}, {"id": "f2", "type": "textarea", "label": "Add a leaf and write or draw that thing on it."}, {"id": "f3", "type": "textarea", "label": "What do you want to add a leaf for next?"}]'::jsonb, array['self-esteem', 'children', 'art']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('friendship-starter-cue-cards-craft', 'Friendship Starter Cue Cards Craft', 'kids'::resource_kind, 'A child decorates cards with lines for starting or joining a conversation.', 'Use it to give a child something concrete to say instead of freezing up.', array['Children']::text[], '20 minutes', 'Have the child decorate a small stack of cards, each with a simple opener like can I play too or what''s your favorite game, then practice saying each one out loud with the parent before trying it at school or a playdate; the parent''s role is to role-play both parts and celebrate any attempt at using a card, not only the ones that land well.', '[{"id": "f0", "type": "textarea", "label": "Write or draw one thing I could say to start talking to someone."}, {"id": "f1", "type": "textarea", "label": "Practice saying it out loud to a grown-up first."}, {"id": "f2", "type": "textarea", "label": "Who could I try this with this week?"}, {"id": "f3", "type": "textarea", "label": "What happened when I tried it?"}]'::jsonb, array['social anxiety', 'children', 'art']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('missing-you-meter-craft', 'Missing You Meter Craft', 'kids'::resource_kind, 'A child builds and colors a dial that shows how much they miss someone each day.', 'Use it to give a child language for changing grief intensity instead of one flat feeling.', array['Children']::text[], '30 minutes', 'Have the child decorate a paper dial with a moving arrow or paperclip spinner, labeling sections from ''a little'' to ''a lot,'' then set it where the parent can see it. Each evening the parent asks the child to move the arrow and briefly says what they notice, without pushing for more detail than the child offers. Children often move the arrow quickly and go back to playing, which is normal grief for their age; the parent''s job is steady noticing, not a long conversation every time. Flag it as a caution if the arrow stays stuck on ''a lot'' for many days in a row.', '[{"id": "f0", "type": "textarea", "label": "I am making a meter to show how much I miss someone."}, {"id": "f1", "type": "textarea", "label": "Today my meter says I miss them…"}, {"id": "f2", "type": "textarea", "label": "One thing that made today''s number go up or down…"}, {"id": "f3", "type": "textarea", "label": "One thing that helps me when the number is high…"}, {"id": "f4", "type": "textarea", "label": "Something I want to tell the person I miss…"}]'::jsonb, array['grief and loss', 'children', 'art']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('okay-not-okay-touch-sort-craft', 'Okay Not Okay Touch Sort Craft', 'kids'::resource_kind, 'A child sorts picture cards into okay and not okay touch, then decorates a keep card.', 'Use it to build a child''s vocabulary for touch safety rules in an age-appropriate way.', array['Children']::text[], '20 minutes', 'Give the child simple picture cards (a high-five, a hug from a stranger, a doctor visit with a parent present) to sort into ''okay'' and ''not okay'' piles, then have them decorate a small card listing their own safe adults to keep. This stays at the level of general safety rules, never asking the child to describe their own experiences. If a child discloses any abuse during the activity, stop, respond calmly, and follow your mandated reporting duties right away rather than continuing the craft. The parent reviews the finished safe-adults card together at home.', '[{"id": "f0", "type": "textarea", "label": "I am sorting cards into okay touch and not okay touch."}, {"id": "f1", "type": "textarea", "label": "One okay touch is…"}, {"id": "f2", "type": "textarea", "label": "One not okay touch is…"}, {"id": "f3", "type": "textarea", "label": "A safe grown-up I can tell if something feels not okay is…"}, {"id": "f4", "type": "textarea", "label": "What I can say if a touch feels not okay…"}]'::jsonb, array['sexual abuse', 'children', 'body safety']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('coping-spinner-wheel-craft', 'Coping Spinner Wheel Craft', 'kids'::resource_kind, 'A child builds a spinner of coping ideas to use when big feelings show up.', 'Use it to give a child a playful, physical way to pick a coping skill in the moment.', array['Children']::text[], '30 minutes', 'Help the child decorate a paper wheel divided into sections, each drawn with one coping idea the child chose themselves (squeeze a pillow, get a hug, draw, jump in place), attach a spinning arrow with a paper fastener, and post it somewhere accessible. When a big feeling hits, the parent invites the child to spin instead of picking for them, which keeps the choice in the child''s hands and lowers a power struggle over which skill to use. Some children spin repeatedly hoping for a favorite section; that''s fine early on, and the parent can gently note it rather than restrict spins.', '[{"id": "f0", "type": "textarea", "label": "I am building a spinner of things that help me feel better."}, {"id": "f1", "type": "textarea", "label": "One thing I''ll put on my spinner is…"}, {"id": "f2", "type": "textarea", "label": "Today I spun and landed on…"}, {"id": "f3", "type": "textarea", "label": "Did it help? A little, some, or a lot…"}, {"id": "f4", "type": "textarea", "label": "One more idea I want to add to my spinner…"}]'::jsonb, array['coping skills', 'children', 'art']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('real-vs-edited-pictures-sorting-craft', 'Real vs Edited Pictures Sorting Craft', 'kids'::resource_kind, 'A child sorts printed pictures into real and edited piles, then builds a poster about it.', 'Use it to build a child''s early media literacy about altered appearance images.', array['Children']::text[], '30 minutes', 'Print or cut out a mix of ordinary snapshot photos and obviously edited or filtered images, and have the child sort them into ''real'' and ''made to look different'' piles, then glue their sorted favorites onto a poster with simple labels. Use the sorting to talk about how pictures people see online are often changed, without naming specific bodies as good or bad in the process. Parents can extend this at home by pointing out an edited photo together when one comes up naturally, keeping the tone curious rather than alarmed.', '[{"id": "f0", "type": "textarea", "label": "I am sorting pictures into real and made to look different."}, {"id": "f1", "type": "textarea", "label": "One clue that told me a picture was edited…"}, {"id": "f2", "type": "textarea", "label": "A real picture I liked and why…"}, {"id": "f3", "type": "textarea", "label": "One thing I want to remember when I see pictures online…"}]'::jsonb, array['body image', 'children', 'media']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('mirror-move-communication-game', 'Mirror Move Communication Game', 'game'::resource_kind, 'A pairs game where one player mirrors the other''s slow movements without talking.', 'Use it to warm up a group''s nonverbal attention and reading of another person''s cues.', array['Teens', 'Adults', 'Groups']::text[], '15 minutes', 'Pairs face each other and one player leads with slow movements while the other mirrors as closely as possible without either speaking, switching leaders halfway through; then the group debriefs on what it took to stay in sync. Pairs often speed up or start laughing and drop the mirroring; that''s fine to let happen and then ask what broke the connection. Works well as an opener before a session on communication or attention.', '[{"id": "f0", "type": "textarea", "label": "Who led first, and who followed?"}, {"id": "f1", "type": "textarea", "label": "What made it easy to stay in sync?"}, {"id": "f2", "type": "textarea", "label": "What made it hard?"}, {"id": "f3", "type": "textarea", "label": "How did it feel to lead versus to follow?"}, {"id": "f4", "type": "textarea", "label": "What does this remind you of in a real conversation?"}]'::jsonb, array['communication', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('puzzle-box-teamwork-challenge', 'Puzzle Box Teamwork Challenge', 'game'::resource_kind, 'A timed group challenge to solve a set of small puzzles together using only teamwork.', 'Use it to surface a group''s real problem-solving habits under a bit of time pressure.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Give the group a handful of small puzzles or riddles to solve together within a set time limit, with a rule that no one person can hold or solve a puzzle alone. Groups often let one confident member take over; if that happens, let it play out and raise it directly in the debrief rather than intervening mid-challenge. The debrief question matters more than whether the group finishes in time.', '[{"id": "f0", "type": "textarea", "label": "What role did you naturally fall into during the challenge?"}, {"id": "f1", "type": "textarea", "label": "Did everyone''s ideas get heard? Why or why not?"}, {"id": "f2", "type": "textarea", "label": "What worked well as a team?"}, {"id": "f3", "type": "textarea", "label": "What would you do differently next time?"}, {"id": "f4", "type": "textarea", "label": "How does this compare to how your group usually solves problems?"}]'::jsonb, array['problem solving', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('mindful-freeze-game', 'Mindful Freeze Game', 'game'::resource_kind, 'A movement game where players freeze on a signal and notice one sense for a full minute.', 'Use it to give a group a playful, embodied taste of a mindful pause.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'Players move around the room until a bell or clap signals freeze, then hold still for a full minute while silently noticing one assigned sense, sound, touch, or sight, before moving again on the next signal. Younger players often want to talk or peek at others during the freeze; a quiet reminder that noticing is silent usually resets it. Rotate through all the senses over a few rounds before the debrief.', '[{"id": "f0", "type": "textarea", "label": "Which sense did you notice this round?"}, {"id": "f1", "type": "textarea", "label": "What''s one thing you noticed that you''d normally miss?"}, {"id": "f2", "type": "textarea", "label": "Was it easy or hard to stay still?"}, {"id": "f3", "type": "textarea", "label": "Which sense was hardest to focus on?"}, {"id": "f4", "type": "textarea", "label": "When could you try a freeze like this on your own?"}]'::jsonb, array['mindfulness', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('habit-highway-board-game', 'Habit Highway Board Game', 'game'::resource_kind, 'A board game where players advance by completing small habit-building actions each turn.', 'Use it to make practicing a new habit feel like play instead of one more chore.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Players take turns rolling a die and moving along a simple paper highway, landing on spaces that ask them to name or actually do a small piece of a habit they''re building, such as naming one cue or describing one obstacle. Players sometimes rush past a space without really answering it; the parent or clinician running the game can ask a quick follow-up before the next turn. Keep the board and add new spaces as the group''s habits change.', '[{"id": "f0", "type": "textarea", "label": "What habit are you building for this game?"}, {"id": "f1", "type": "textarea", "label": "Name one cue that reminds you to do your habit."}, {"id": "f2", "type": "textarea", "label": "Name one thing that gets in the way of your habit."}, {"id": "f3", "type": "textarea", "label": "Describe a time this week your habit went well."}, {"id": "f4", "type": "textarea", "label": "What space on the board was hardest to answer?"}]'::jsonb, array['habits', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('change-talk-card-game', 'Change Talk Card Game', 'game'::resource_kind, 'A card game where players draw prompts about their own reasons for making a change.', 'Use it to help a group notice and voice their own reasons for wanting to change.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Players take turns drawing a card with a prompt about reasons for or against a change they''re considering, answering out loud before passing to the next player; the group can respond with a follow-up question but not advice. Players sometimes answer in generalities to avoid saying something personal; a follow-up question from the group usually draws out something more specific. Debrief by asking which card''s answer surprised the player who drew it.', '[{"id": "f0", "type": "textarea", "label": "Draw a card and read the prompt out loud."}, {"id": "f1", "type": "textarea", "label": "What''s your honest answer?"}, {"id": "f2", "type": "textarea", "label": "What''s one reason you might not want to change?"}, {"id": "f3", "type": "textarea", "label": "What''s one reason you might?"}, {"id": "f4", "type": "textarea", "label": "Which of your own answers surprised you?"}]'::jsonb, array['motivation', 'motivational interviewing', 'group']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('five-senses-grounding-relay', 'Five Senses Grounding Relay', 'game'::resource_kind, 'A turn-based group game where each player names a present-moment sensory detail.', 'Use it to practice quick grounding as a shared, low-pressure group skill.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Players sit in a circle and pass a small object; whoever holds it names one thing they can currently see, hear, feel, smell or taste, then passes it on for a new turn. Keep the pace brisk and light, and if someone freezes, let them pass and try again next round rather than putting them on the spot. This works well as a session opener when the group seems keyed up, and the debrief should stay in the present moment rather than opening into any one person''s history.', '[{"id": "f0", "type": "textarea", "label": "One thing you can see right now."}, {"id": "f1", "type": "textarea", "label": "One thing you can hear right now."}, {"id": "f2", "type": "textarea", "label": "One thing you can feel right now."}, {"id": "f3", "type": "textarea", "label": "Debrief: which sense was easiest for you to notice today?"}, {"id": "f4", "type": "textarea", "label": "Debrief: how does your body feel now compared to before we started?"}]'::jsonb, array['PTSD and trauma', 'grounding', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('worry-or-fact-card-sort-game', 'Worry or Fact Card Sort Game', 'game'::resource_kind, 'Players take turns sorting statement cards into worry piles and fact piles.', 'Use it to build quick, shared practice telling a worry apart from a checked fact.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Prepare a deck of short statement cards mixing worries with verifiable facts, and have players take turns drawing one and sorting it into a worry pile or a fact pile, explaining their reasoning to the group. Disagreement is the useful part; let the group debate a card rather than settling it too fast. People often sort a worry into the fact pile because it feels certain; use those moments to name the difference between feeling sure and being sure. Close with a debrief on which cards were hardest to sort and why.', '[{"id": "f0", "type": "textarea", "label": "Read your card out loud to the group."}, {"id": "f1", "type": "textarea", "label": "Worry pile or fact pile: where does it go, and why?"}, {"id": "f2", "type": "textarea", "label": "Does anyone see it differently?"}, {"id": "f3", "type": "textarea", "label": "Debrief: which card was hardest to sort today?"}, {"id": "f4", "type": "textarea", "label": "Debrief: what made a worry feel like a fact in the moment?"}]'::jsonb, array['anxiety', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('behavioral-activation-snakes-and-ladders', 'Behavioral Activation Snakes and Ladders', 'game'::resource_kind, 'A board game where ladders are small activated steps and snakes are avoidance.', 'Use it to make behavioral activation steps visible and a little bit playful.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Build a simple board with the client or group where landing on a ladder square means naming one small activity that lifted mood before, and landing on a snake square means naming one avoidance pattern that has crept in. Players take turns rolling and moving, and roleplaying the ladder square out loud, even briefly, adds more than just reading it silently. Some players want to skip the snake squares; let the group notice that pull and name it rather than forcing a confession. Debrief on which squares felt most true today.', '[{"id": "f0", "type": "textarea", "label": "Ladder square: name one small activity that has lifted your mood before."}, {"id": "f1", "type": "textarea", "label": "Snake square: name one avoidance pattern you''ve noticed lately."}, {"id": "f2", "type": "textarea", "label": "Which square did you land on this turn?"}, {"id": "f3", "type": "textarea", "label": "Debrief: which ladder could you actually try this week?"}, {"id": "f4", "type": "textarea", "label": "Debrief: which snake would be hardest to climb back up from?"}]'::jsonb, array['depression', 'behavioral activation', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('urge-surfing-board-game', 'Urge Surfing Board Game', 'game'::resource_kind, 'Players move a token along a wave-shaped board as an urge rises and falls.', 'Use it to practice riding out an urge as a shared, turn-based activity.', array['Groups', 'Adults']::text[], '20 minutes', 'Draw or print a simple wave-shaped path and have players take turns rolling a die to move a token along it, narrating what an urge at that point on the wave might feel like and one thing that could help ride it out. Reaching the top of the wave without ''giving in'' by moving off the board is the shared goal, not competing to finish first. Players sometimes want to skip past the peak quickly; slow that turn down since it is the most useful part to practice narrating. Close with a debrief on which coping move on the board felt most realistic.', '[{"id": "f0", "type": "textarea", "label": "Roll and move: where is your token on the wave?"}, {"id": "f1", "type": "textarea", "label": "Describe what an urge at this point might feel like."}, {"id": "f2", "type": "textarea", "label": "Name one thing that could help you ride out this point."}, {"id": "f3", "type": "textarea", "label": "Debrief: which point on the wave is hardest for you in real life?"}, {"id": "f4", "type": "textarea", "label": "Debrief: which coping move felt most realistic to actually use?"}]'::jsonb, array['addiction', 'urges', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('cool-down-card-race-game', 'Cool Down Card Race Game', 'game'::resource_kind, 'Players race to name a calming strategy after drawing a frustrating scenario card.', 'Use it to build fast, shared recall of calming strategies under mild pressure.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'Prepare a deck of short frustrating scenario cards, such as losing a game or being interrupted, and have players take turns drawing one and racing to name a calming strategy before a short timer runs out. Getting a strategy out under the timer, even an imperfect one, is the point, not being clever; keep the mood light and let players cheer each other on. Some players freeze under the timer; let them ask the group for a hint rather than passing in silence. Debrief on which strategies actually felt doable versus which just sounded good.', '[{"id": "f0", "type": "textarea", "label": "Read your scenario card out loud."}, {"id": "f1", "type": "textarea", "label": "Name a calming strategy before the timer runs out."}, {"id": "f2", "type": "textarea", "label": "Did you beat the timer? How did it feel?"}, {"id": "f3", "type": "textarea", "label": "Debrief: which strategy would you actually use in real life?"}, {"id": "f4", "type": "textarea", "label": "Debrief: which one just sounded good but wouldn''t work for you?"}]'::jsonb, array['anger management', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('panic-alarm-board-race', 'Panic Alarm Board Race', 'game'::resource_kind, 'A short board game where landing on a coping space earns a bonus move.', 'Use it to rehearse panic coping steps in a low-pressure, playful format.', array['Children', 'Groups']::text[], '20 minutes', 'Draw a simple path board with squares that are either a body sensation or a coping skill; players take turns rolling and moving, naming the sensation or acting out the coping skill to earn an extra space, and the first to finish wins; debrief on which coping space felt most doable, and slow down any player who is racing through the naming step to win faster.', '[{"id": "f0", "type": "textarea", "label": "Which coping space would you want to land on first?"}, {"id": "f1", "type": "textarea", "label": "Which sensation square felt easiest to name?"}, {"id": "f2", "type": "textarea", "label": "Which coping skill felt hardest to actually do?"}, {"id": "f3", "type": "textarea", "label": "Which one will you try for real this week?"}]'::jsonb, array['panic attacks', 'play', 'children']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('kindness-points-family-challenge', 'Kindness Points Family Challenge', 'game'::resource_kind, 'Family members earn points for small kind acts and reflect on them together.', 'Use it to make everyday cooperation and kindness visible and noticed.', array['Adults', 'Children', 'Groups']::text[], 'One week', 'Each family member, including the parents, logs one small kind act toward another member each day on a shared board, tallies it at the end of the week, and takes turns naming an act that stood out to them; watch for it drifting into sibling competition, and steer the debrief back toward noticing rather than counting who did more.', '[{"id": "f0", "type": "textarea", "label": "What kind act will I try to do for someone in my family today?"}, {"id": "f1", "type": "textarea", "label": "Whose kind act toward me stood out this week?"}, {"id": "f2", "type": "textarea", "label": "Which was easier, giving kindness or noticing it?"}, {"id": "f3", "type": "textarea", "label": "What is one kind act we want to keep doing after this week?"}]'::jsonb, array['parenting', 'family', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('new-parent-bingo', 'New Parent Bingo', 'game'::resource_kind, 'A bingo card of common new-parent moments played in a support group.', 'Use it to normalize the range of new-parent experience in a light format.', array['Adults', 'Groups']::text[], '20 minutes', 'Each square names a common moment, like crying in the bathroom, forgetting to eat, or googling something worrying at 2am; players mark squares that match their week and call bingo when a row fills, then the group debriefs on which square surprised them to see written down; let anyone skip a square that feels too close to real distress that day.', '[{"id": "f0", "type": "textarea", "label": "Which square matched your week exactly?"}, {"id": "f1", "type": "textarea", "label": "Which square surprised you to see written down?"}, {"id": "f2", "type": "textarea", "label": "Which square would you add for next time?"}, {"id": "f3", "type": "textarea", "label": "What was it like to hear others share the same square?"}]'::jsonb, array['perinatal and postpartum', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('social-risk-ladder-dice-game', 'Social Risk Ladder Dice Game', 'game'::resource_kind, 'Rolls a die to attempt increasingly bold social micro-challenges in session.', 'Use it to rehearse graded social risk-taking in a playful, low-stakes format.', array['Teens', 'Groups']::text[], '20 minutes', 'Rank six small social challenges from easiest to hardest, such as three seconds of eye contact, asking someone''s name, or disagreeing politely, and assign one to each number on a die; players take turns rolling and attempting that number''s challenge with another player, then the group debriefs on what made it easier or harder than expected; let a player trade down one level rather than skip a hard roll.', '[{"id": "f0", "type": "textarea", "label": "Which challenge felt easiest when you rolled it?"}, {"id": "f1", "type": "textarea", "label": "Which challenge felt hardest?"}, {"id": "f2", "type": "textarea", "label": "What made a challenge easier once you actually tried it?"}, {"id": "f3", "type": "textarea", "label": "Which challenge would you want to practice again for real?"}]'::jsonb, array['social anxiety', 'exposure', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('grief-support-bingo', 'Grief Support Bingo', 'game'::resource_kind, 'A bingo card of small support actions that players check off and discuss.', 'Use it to make asking for and offering grief support feel doable in a group.', array['Groups', 'Adults']::text[], '30 minutes', 'Give each player a bingo card filled with small support actions instead of numbers — things like ''texted someone the person''s name,'' ''let myself cry for two minutes,'' or ''said no to an event I wasn''t ready for.'' Over the week between sessions, players mark a square each time they do or receive one of the actions, and the group compares cards at the next meeting, going row by row on what helped. A sparse card in a hard week is data about capacity, not a failure to play. Close with a debrief question: which square was hardest to earn, and why?', '[{"id": "f0", "type": "textarea", "label": "One square I marked this week was…"}, {"id": "f1", "type": "textarea", "label": "What made that action possible for me…"}, {"id": "f2", "type": "textarea", "label": "One square I couldn''t get to and why…"}, {"id": "f3", "type": "textarea", "label": "A support action I''d add to my own bingo card…"}]'::jsonb, array['grief and loss', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('safe-adults-scavenger-hunt-game', 'Safe Adults Scavenger Hunt Game', 'game'::resource_kind, 'Kids take turns finding safe-adult cues around a room, then debrief on their own list.', 'Use it to help a group of children practice naming safe adults in their own life.', array['Children', 'Groups']::text[], '30 minutes', 'Hide picture cards showing traits of safe adults (someone who listens, someone the child knows well, someone who keeps promises) around the room, and have children take turns finding one card per round and reading its trait aloud. Afterward, have each child name one real safe adult in their life who fits a trait from the cards. Keep it focused on identifying support, never on any past event; if a child discloses abuse during the debrief, pause the game, respond calmly, and follow your mandated reporting duties before continuing. Debrief question: what makes someone easy to tell things to?', '[{"id": "f0", "type": "textarea", "label": "One trait card I found said…"}, {"id": "f1", "type": "textarea", "label": "A safe adult in my life who has that trait…"}, {"id": "f2", "type": "textarea", "label": "How that person shows me they''re safe to talk to…"}, {"id": "f3", "type": "textarea", "label": "Debrief: what makes someone easy to tell things to?"}]'::jsonb, array['sexual abuse', 'children', 'group']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('coping-skills-draw-and-guess-game', 'Coping Skills Draw and Guess Game', 'game'::resource_kind, 'Players sketch a coping skill in turns while others guess it, then debrief what stuck.', 'Use it to make naming and remembering coping skills fun for a group.', array['Groups', 'Children']::text[], '20 minutes', 'Give each player a turn drawing a coping skill from a hidden list — no words or letters allowed — while the rest of the group guesses within a set time limit before rotating to the next artist. Keep score loosely or skip it entirely; the value is in seeing the same handful of skills drawn and guessed repeatedly until they stick. Some players freeze up when it''s their turn to draw; let them choose from three cards instead of drawing blind if that helps. Close with a debrief question: which skill would you actually reach for this week?', '[{"id": "f0", "type": "textarea", "label": "The coping skill I drew or guessed that I''d forgotten about…"}, {"id": "f1", "type": "textarea", "label": "A coping skill that came up a lot in the game…"}, {"id": "f2", "type": "textarea", "label": "Debrief: which skill would you actually reach for this week?"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz),
  ('approach-or-avoid-card-game', 'Approach or Avoid Card Game', 'game'::resource_kind, 'Players draw scenario cards and vote approach or avoid before comparing reasoning.', 'Use it to practice spotting avoidance patterns together in a low-stakes group format.', array['Groups', 'Teens']::text[], '30 minutes', 'Deal out scenario cards describing a feared situation, not necessarily the players'' own fears, and on each turn the group votes approach or avoid before the card-holder reveals what a values-driven choice might look like. Rotate the card-holder each round so everyone gets a turn leading. Some players will vote avoid reflexively for every card; use that as a debrief moment rather than correcting it in the round. Close with the debrief question: which vote surprised you about yourself?', '[{"id": "f0", "type": "textarea", "label": "A scenario card where I voted approach…"}, {"id": "f1", "type": "textarea", "label": "A scenario card where I voted avoid…"}, {"id": "f2", "type": "textarea", "label": "What made the difference between those two votes for me…"}, {"id": "f3", "type": "textarea", "label": "Debrief: which vote surprised you about yourself?"}]'::jsonb, array['phobias', 'group', 'play']::text[], '2026-09-20T15:00:00+00:00'::timestamptz)
